import java.util.*;
import java.util.concurrent.*;

class Position {
    private final double x;
    private final double y;

    public Position(double x, double y) {
        this.x = x;
        this.y = y;
    }

    public double getX() {
        return x;
    }

    public double getY() {
        return y;
    }

    @Override
    public String toString() {
        return String.format("Position(%.2f, %.2f)", x, y);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        Position position = (Position) obj;
        return Double.compare(position.x, x) == 0 && 
               Double.compare(position.y, y) == 0;
    }

    @Override
    public int hashCode() {
        return Objects.hash(x, y);
    }
}

class DelegatingDeviceTracker {
    private final ConcurrentHashMap<String, Position> locations;
    private final Map<String, Position> unmodifiableMap;

    public DelegatingDeviceTracker(Map<String, Position> initialPositions) {
        this.locations = new ConcurrentHashMap<>(initialPositions);
        this.unmodifiableMap = Collections.unmodifiableMap(locations);
    }

    public Position getPosition(String gadgetId) {
        return locations.get(gadgetId);
    }

    public boolean updatePosition(String gadgetId, Position newPosition) {
        if (newPosition == null) {
            throw new IllegalArgumentException("Position cannot be null");
        }
        // Only update if the gadget ID already exists
        return locations.replace(gadgetId, locations.get(gadgetId), newPosition) ||
               (locations.containsKey(gadgetId) && 
                locations.replace(gadgetId, newPosition) != null);
    }

    public Map<String, Position> getLiveUnmodifiableView() {
        return unmodifiableMap;
    }

    public Map<String, Position> getStaticSnapshot() {
        return Collections.unmodifiableMap(new HashMap<>(locations));
    }

    public int getDeviceCount() {
        return locations.size();
    }
}

public class DeviceTrackerDemo {

    public static void main(String[] args) {
        // Initialize the tracker with some gadgets
        Map<String, Position> initialPositions = new HashMap<>();
        initialPositions.put("phone1", new Position(10.0, 20.0));
        initialPositions.put("tablet1", new Position(30.0, 40.0));
        initialPositions.put("laptop1", new Position(50.0, 60.0));
        initialPositions.put("watch1", new Position(70.0, 80.0));

        DelegatingDeviceTracker tracker = new DelegatingDeviceTracker(initialPositions);

        System.out.println("Initial positions:");
        tracker.getLiveUnmodifiableView().forEach((id, pos) -> 
            System.out.println("  " + id + ": " + pos));

        // Create an ExecutorService with 2 threads (plus main thread = 3 total)
        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Create tasks to update positions concurrently
        Runnable updateTask1 = () -> {
            String threadName = Thread.currentThread().getName();
            for (int i = 0; i < 5; i++) {
                String gadgetId = "phone1";
                Position newPos = new Position(10.0 + i * 2, 20.0 + i * 2);
                boolean updated = tracker.updatePosition(gadgetId, newPos);
                if (updated) {
                    System.out.println(threadName + " updated " + gadgetId + 
                                     " to " + newPos);
                }

                // Also try to update a non-existent gadget (should fail)
                boolean failedUpdate = tracker.updatePosition("nonexistent", 
                                                             new Position(0, 0));
                if (!failedUpdate && i == 0) {
                    System.out.println(threadName + 
                                     " correctly failed to update non-existent gadget");
                }

                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        };

        Runnable updateTask2 = () -> {
            String threadName = Thread.currentThread().getName();
            for (int i = 0; i < 5; i++) {
                String gadgetId = "tablet1";
                Position newPos = new Position(30.0 - i * 3, 40.0 - i * 3);
                boolean updated = tracker.updatePosition(gadgetId, newPos);
                if (updated) {
                    System.out.println(threadName + " updated " + gadgetId + 
                                     " to " + newPos);
                }

                // Read position of another gadget
                Position laptopPos = tracker.getPosition("laptop1");
                if (i == 2) {
                    System.out.println(threadName + " read laptop1 position: " + 
                                     laptopPos);
                }

                try {
                    Thread.sleep(120);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        };

        // Submit tasks to executor
        Future<?> future1 = executor.submit(updateTask1);
        Future<?> future2 = executor.submit(updateTask2);

        // Main thread also performs some operations
        System.out.println("\nMain thread performing operations...");
        for (int i = 0; i < 3; i++) {
            // Update laptop position from main thread
            Position newLaptopPos = new Position(50.0 + i * 5, 60.0 + i * 5);
            tracker.updatePosition("laptop1", newLaptopPos);
            System.out.println("Main thread updated laptop1 to " + newLaptopPos);

            try {
                Thread.sleep(200);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }

        // Wait for tasks to complete
        try {
            future1.get();
            future2.get();
        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        }

        // Shutdown executor
        executor.shutdown();
        try {
            if (!executor.awaitTermination(1, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }

        System.out.println("\nFinal positions (live view):");
        Map<String, Position> liveView = tracker.getLiveUnmodifiableView();
        liveView.forEach((id, pos) -> 
            System.out.println("  " + id + ": " + pos));

        System.out.println("\nTaking a snapshot...");
        Map<String, Position> snapshot = tracker.getStaticSnapshot();

        // Update a position after taking snapshot
        tracker.updatePosition("watch1", new Position(100.0, 110.0));

        System.out.println("\nSnapshot (unchanged after update):");
        snapshot.forEach((id, pos) -> 
            System.out.println("  " + id + ": " + pos));

        System.out.println("\nLive view (shows updated watch1):");
        liveView.forEach((id, pos) -> 
            System.out.println("  " + id + ": " + pos));

        // Demonstrate thread safety by trying to modify returned maps
        try {
            liveView.put("newGadget", new Position(0, 0));
        } catch (UnsupportedOperationException e) {
            System.out.println("\nCorrectly prevented modification of live view");
        }

        try {
            snapshot.put("newGadget", new Position(0, 0));
        } catch (UnsupportedOperationException e) {
            System.out.println("Correctly prevented modification of snapshot");
        }

        System.out.println("\nTotal devices tracked: " + tracker.getDeviceCount());
    }
}

import java.util.*;
import java.util.concurrent.*;

public class DelegatingDeviceTracker {
    private final ConcurrentHashMap<String, Position> locations;
    private final Map<String, Position> unmodifiableMap;

    public DelegatingDeviceTracker(Map<String, Position> initialPositions) {
        this.locations = new ConcurrentHashMap<>(initialPositions);
        this.unmodifiableMap = Collections.unmodifiableMap(locations);
    }

    public Position getPosition(String gadgetId) {
        Position pos = locations.get(gadgetId);
        return pos == null ? null : new Position(pos);
    }

    public boolean updatePosition(String gadgetId, Position newPosition) {
        if (newPosition == null) {
            return false;
        }
        Position existingPosition = locations.get(gadgetId);
        if (existingPosition != null) {
            locations.put(gadgetId, new Position(newPosition));
            return true;
        }
        return false;
    }

    public Map<String, Position> getLiveUnmodifiableView() {
        return unmodifiableMap;
    }

    public Map<String, Position> getStaticSnapshot() {
        Map<String, Position> snapshot = new HashMap<>();
        for (Map.Entry<String, Position> entry : locations.entrySet()) {
            snapshot.put(entry.getKey(), new Position(entry.getValue()));
        }
        return Collections.unmodifiableMap(snapshot);
    }

    public static void main(String[] args) {
        // Initialize with some gadget positions
        Map<String, Position> initialPositions = new HashMap<>();
        initialPositions.put("gadget1", new Position(10, 20));
        initialPositions.put("gadget2", new Position(30, 40));
        initialPositions.put("gadget3", new Position(50, 60));

        DelegatingDeviceTracker tracker = new DelegatingDeviceTracker(initialPositions);

        // Create ExecutorService with 2 threads (plus main thread = 3 total)
        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Task 1: Continuously update positions
        executor.submit(() -> {
            String threadName = Thread.currentThread().getName();
            Random random = new Random();
            for (int i = 0; i < 5; i++) {
                String gadgetId = "gadget" + (random.nextInt(3) + 1);
                Position newPos = new Position(random.nextInt(100), random.nextInt(100));
                boolean updated = tracker.updatePosition(gadgetId, newPos);
                System.out.println("[" + threadName + "] Updating " + gadgetId + 
                                 " to " + newPos + " - Success: " + updated);
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });

        // Task 2: Continuously read positions
        executor.submit(() -> {
            String threadName = Thread.currentThread().getName();
            for (int i = 0; i < 5; i++) {
                String gadgetId = "gadget" + ((i % 3) + 1);
                Position pos = tracker.getPosition(gadgetId);
                System.out.println("[" + threadName + "] Reading " + gadgetId + 
                                 " position: " + pos);
                try {
                    Thread.sleep(150);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });

        // Main thread operations
        try {
            Thread.sleep(200);

            // Try to update a non-existent gadget
            boolean failedUpdate = tracker.updatePosition("gadget99", new Position(99, 99));
            System.out.println("[Main Thread] Attempt to update non-existent gadget99: " + failedUpdate);

            // Get live view
            Map<String, Position> liveView = tracker.getLiveUnmodifiableView();
            System.out.println("[Main Thread] Live view size: " + liveView.size());

            Thread.sleep(300);

            // Get static snapshot
            Map<String, Position> snapshot = tracker.getStaticSnapshot();
            System.out.println("[Main Thread] Snapshot of all positions:");
            for (Map.Entry<String, Position> entry : snapshot.entrySet()) {
                System.out.println("  " + entry.getKey() + ": " + entry.getValue());
            }

            // Demonstrate that snapshot is unmodifiable
            try {
                snapshot.put("newGadget", new Position(0, 0));
            } catch (UnsupportedOperationException e) {
                System.out.println("[Main Thread] Snapshot is unmodifiable - caught expected exception");
            }

            // Demonstrate that live view is unmodifiable
            try {
                liveView.put("newGadget", new Position(0, 0));
            } catch (UnsupportedOperationException e) {
                System.out.println("[Main Thread] Live view is unmodifiable - caught expected exception");
            }

        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        // Shutdown executor
        executor.shutdown();
        try {
            if (!executor.awaitTermination(2, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }

        System.out.println("\n[Main Thread] Final positions:");
        Map<String, Position> finalSnapshot = tracker.getStaticSnapshot();
        for (Map.Entry<String, Position> entry : finalSnapshot.entrySet()) {
            System.out.println("  " + entry.getKey() + ": " + entry.getValue());
        }
    }
