public class DelegatingDeviceTracker {
    private final ConcurrentHashMap<String, Position> locations;
    private final Map<String, Position> unmodifiableMap;

    public DelegatingDeviceTracker(Map<String, Position> initialPositions) {
        this.locations = new ConcurrentHashMap<>(initialPositions);
        this.unmodifiableMap = Collections.unmodifiableMap(this.locations);
    }

    // Get position of a specific gadget
    public Position getPosition(String gadgetId) {
        Position pos = locations.get(gadgetId);
        return pos == null ? null : new Position(pos.getX(), pos.getY());
    }

    // Update position of a gadget (only if it exists)
    public boolean updatePosition(String gadgetId, int x, int y) {
        Position newPos = new Position(x, y);
        return locations.replace(gadgetId, locations.get(gadgetId), newPos);
    }

    // Returns a live unmodifiable view backed by the original data
    public Map<String, Position> getLivePositions() {
        return unmodifiableMap;
    }

    // Returns a static snapshot of the current state as an unmodifiable map
    public Map<String, Position> getSnapshotPositions() {
        Map<String, Position> snapshot = new HashMap<>();
        for (Map.Entry<String, Position> entry : locations.entrySet()) {
            Position pos = entry.getValue();
            snapshot.put(entry.getKey(), new Position(pos.getX(), pos.getY()));
        }
        return Collections.unmodifiableMap(snapshot);
    }

