    }

    public Coordinate getLocation(String robotId) {
        return robotLocations.get(robotId);
    }

    public boolean updateLocation(String robotId, Coordinate newLocation) {
        if (newLocation == null) {
            throw new IllegalArgumentException("Coordinate cannot be null");
        }

        // Only update if the robot ID exists
        return robotLocations.replace(robotId, robotLocations.get(robotId), newLocation);
    }

    public boolean updateLocationIfExists(String robotId, Coordinate newLocation) {
        if (newLocation == null) {
            throw new IllegalArgumentException("Coordinate cannot be null");
        }

        // Alternative implementation using computeIfPresent
        return robotLocations.computeIfPresent(robotId, (k, v) -> newLocation) != null;
    }

