        this.robotLocations = new ConcurrentHashMap<>(initialLocations);
    }

    public Coordinates getCoordinates(String robotId) {
        Coordinates coords = robotLocations.get(robotId);
        return coords != null ? new Coordinates(coords.x, coords.y) : null;
