import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.Callable;

public class SolarSquirrels {
    private final List<String> squirrelIdentifiers;

    public SolarSquirrels() {
        this.squirrelIdentifiers = Collections.unmodifiableList(
            Arrays.asList("Nutty", "Whisk", "Fidget")
        );
    }

    public boolean isSquirrel(String identifier) {
        return squirrelIdentifiers.contains(identifier);
    }

    public String getSquirrelIdentifiers() {
        return squirrelIdentifiers.toString();
    }

    public static void main(String[] args) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        SolarSquirrels solarSquirrels = new SolarSquirrels();

        Callable<Boolean> checkNutty = () -> {
            return solarSquirrels.isSquirrel("Nutty");
        };

        Callable<Boolean> checkRandom = () -> {
            return solarSquirrels.isSquirrel("Random");
        };

        Runnable printIdentifiers = () -> {
            System.out.println(solarSquirrels.getSquirrelIdentifiers());
        };

        Future<Boolean> nuttyResult = executor.submit(checkNutty);
        Future<Boolean> randomResult = executor.submit(checkRandom);
        executor.execute(printIdentifiers);

        System.out.println("Is Nutty a squirrel? " + nuttyResult.get());
        System.out.println("Is Random a squirrel? " + randomResult.get());

        executor.shutdown();
    }
}

