import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;
import java.util.Random;

public class ParcelMover {

    private static final Random random = new Random();

    static class NotEnoughItemsException extends Exception {
        public NotEnoughItemsException(String message) {
            super(message);
        }
    }

    static class ParcelCount {
        private int count;

        public ParcelCount(int count) {
            this.count = count;
        }

        public int getCount() {
            return count;
        }

        public void setCount(int count) {
            this.count = count;
        }

        public void add(int amount) {
            this.count += amount;
        }

        public void subtract(int amount) {
            this.count -= amount;
        }
    }

    static class Locker {
        private final String name;
        private final ReentrantLock lock;
        private final ParcelCount parcelCount;

        public Locker(String name, int initialCount) {
            this.name = name;
            this.lock = new ReentrantLock();
            this.parcelCount = new ParcelCount(initialCount);
        }

        public String getName() {
            return name;
        }

        public ReentrantLock getLock() {
            return lock;
        }

        public ParcelCount getParcelCount() {
            return parcelCount;
        }
    }

    public static boolean move(Locker source, Locker target, int quantity, 
                              long timeout, TimeUnit unit) throws NotEnoughItemsException {
        long endTime = System.nanoTime() + unit.toNanos(timeout);

        while (System.nanoTime() < endTime) {
            boolean sourceLocked = false;
            boolean targetLocked = false;

            try {
                long remainingTime = endTime - System.nanoTime();
                if (remainingTime <= 0) {
                    return false;
                }

                sourceLocked = source.getLock().tryLock(remainingTime, TimeUnit.NANOSECONDS);
                if (!sourceLocked) {
                    continue;
                }

                remainingTime = endTime - System.nanoTime();
                if (remainingTime <= 0) {
                    return false;
                }

                targetLocked = target.getLock().tryLock(remainingTime, TimeUnit.NANOSECONDS);
                if (!targetLocked) {
                    Thread.sleep(getFixedDelay() + getRandomDelay());
                    continue;
                }

                if (source.getParcelCount().getCount() < quantity) {
                    throw new NotEnoughItemsException("Source locker does not have enough items");
                }

                source.getParcelCount().subtract(quantity);
                target.getParcelCount().add(quantity);
                return true;

            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return false;
            } finally {
                if (targetLocked) {
                    target.getLock().unlock();
                }
                if (sourceLocked) {
                    source.getLock().unlock();
                }
            }
        }

        return false;
    }

    private static long getFixedDelay() {
        return 10;
    }

    private static long getRandomDelay() {
        return random.nextInt(50);
    }

    public static void main(String[] args) {
        Locker locker1 = new Locker("Locker1", 100);
        Locker locker2 = new Locker("Locker2", 50);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        Future<Boolean> future1 = executor.submit(() -> {
            try {
                boolean result = move(locker1, locker2, 30, 5, TimeUnit.SECONDS);
                System.out.println("Thread 1: Move from Locker1 to Locker2 - " + result);
                return result;
            } catch (NotEnoughItemsException e) {
                System.out.println("Thread 1: " + e.getMessage());
                return false;
            }
        });

        Future<Boolean> future2 = executor.submit(() -> {
            try {
                boolean result = move(locker2, locker1, 20, 5, TimeUnit.SECONDS);
                System.out.println("Thread 2: Move from Locker2 to Locker1 - " + result);
                return result;
            } catch (NotEnoughItemsException e) {
                System.out.println("Thread 2: " + e.getMessage());
                return false;
            }
        });

        try {
            Boolean result1 = future1.get();
            Boolean result2 = future2.get();

            System.out.println("Final Locker1 count: " + locker1.getParcelCount().getCount());
            System.out.println("Final Locker2 count: " + locker2.getParcelCount().getCount());
        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        }

        executor.shutdown();
    }
}

