import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;
import java.util.Random;
import java.util.ArrayList;
import java.util.List;

public class DeadlockAvoidanceSwap {

    private static final Random random = new Random();

    public static void main(String[] args) throws InterruptedException {
        Container container1 = new Container("Container1");
        Container container2 = new Container("Container2");

        container1.addElements(10);
        container2.addElements(5);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        CountDownLatch latch = new CountDownLatch(2);

        executor.submit(() -> {
            try {
                boolean result = swap(container1, container2, 3, 5, TimeUnit.SECONDS);
                System.out.println("Thread 1 swap result: " + result);
            } catch (InsufficientElementsException e) {
                System.out.println("Thread 1: " + e.getMessage());
            } finally {
                latch.countDown();
            }
        });

        executor.submit(() -> {
            try {
                boolean result = swap(container2, container1, 2, 5, TimeUnit.SECONDS);
                System.out.println("Thread 2 swap result: " + result);
            } catch (InsufficientElementsException e) {
                System.out.println("Thread 2: " + e.getMessage());
            } finally {
                latch.countDown();
            }
        });

        latch.await();

        System.out.println("Final container1 count: " + container1.getElementCount().getCount());
        System.out.println("Final container2 count: " + container2.getElementCount().getCount());

        executor.shutdown();
    }

    public static boolean swap(Container origin, Container target, int numberOfElements, 
                               long timeout, TimeUnit unit) throws InsufficientElementsException {
        long deadline = System.nanoTime() + unit.toNanos(timeout);

        while (System.nanoTime() < deadline) {
            boolean originLocked = false;
            boolean targetLocked = false;

            try {
                long remainingTime = deadline - System.nanoTime();
                if (remainingTime <= 0) {
                    return false;
                }

                originLocked = origin.getLock().tryLock(remainingTime, TimeUnit.NANOSECONDS);

                if (originLocked) {
                    remainingTime = deadline - System.nanoTime();
                    if (remainingTime <= 0) {
                        return false;
                    }

                    targetLocked = target.getLock().tryLock(remainingTime, TimeUnit.NANOSECONDS);

                    if (targetLocked) {
                        if (origin.getElementCount().getCount() < numberOfElements) {
                            throw new InsufficientElementsException(
                                "Origin container has insufficient elements: " + 
                                origin.getElementCount().getCount() + " < " + numberOfElements);
                        }

                        origin.removeElements(numberOfElements);
                        target.addElements(numberOfElements);
                        return true;
                    }
                }

                if (!targetLocked) {
                    try {
                        Thread.sleep(calculateFixedDelay() + calculateRandomDelay());
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        return false;
                    }
                }

            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return false;
            } finally {
                if (targetLocked) {
                    target.getLock().unlock();
                }
                if (originLocked) {
                    origin.getLock().unlock();
                }
            }
        }

        return false;
    }

    private static long calculateFixedDelay() {
        return 10;
    }

    private static long calculateRandomDelay() {
        return random.nextInt(50);
    }

    static class ElementCount {
        private int count;

        public ElementCount(int count) {
            this.count = count;
        }

        public int getCount() {
            return count;
        }

        public void setCount(int count) {
            this.count = count;
        }
    }

    static class Container {
        private final String name;
        private final ElementCount elementCount;
        private final ReentrantLock lock;

        public Container(String name) {
            this.name = name;
            this.elementCount = new ElementCount(0);
            this.lock = new ReentrantLock();
        }

        public String getName() {
            return name;
        }

        public ElementCount getElementCount() {
            return elementCount;
        }

        public ReentrantLock getLock() {
            return lock;
        }

        public void addElements(int count) {
            elementCount.setCount(elementCount.getCount() + count);
        }

        public void removeElements(int count) {
            elementCount.setCount(elementCount.getCount() - count);
        }
    }

    static class InsufficientElementsException extends Exception {
        public InsufficientElementsException(String message) {
            super(message);
        }
    }
}

