    public static boolean move(Bin sourceBin, Bin targetBin, int widgetsToMove, 
                               long timeout, TimeUnit timeUnit) throws NotEnoughWidgetsException {
        long deadline = System.nanoTime() + timeUnit.toNanos(timeout);

        while (System.nanoTime() < deadline) {
            boolean sourceLocked = false;
            boolean targetLocked = false;

            try {
                long remainingTime = deadline - System.nanoTime();
                if (remainingTime <= 0) {
                    return false;
                }

                sourceLocked = sourceBin.getLock().tryLock(remainingTime, TimeUnit.NANOSECONDS);

                if (sourceLocked) {
                    remainingTime = deadline - System.nanoTime();
                    if (remainingTime <= 0) {
                        return false;
                    }

                    targetLocked = targetBin.getLock().tryLock(remainingTime, TimeUnit.NANOSECONDS);

                    if (targetLocked) {
                        if (sourceBin.getWidgetCount().getCount() >= widgetsToMove) {
                            sourceBin.getWidgetCount().subtract(widgetsToMove);
                            targetBin.getWidgetCount().add(widgetsToMove);
                            return true;
                        } else {
                            throw new NotEnoughWidgetsException(
                                "Source bin " + sourceBin.getName() + " has only " + 
                                sourceBin.getWidgetCount().getCount() + " widgets, but " + 
                                widgetsToMove + " were requested");
                        }
                    }
                }

                if (!targetLocked && System.nanoTime() < deadline) {
                    try {
                        Thread.sleep(calculateFixedDelay() + calculateRandomDelay());
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        return false;
                    }
