import java.util.Random;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;

public class WidgetTransferSystem {

    private static final Random random = new Random();

    static class NotEnoughWidgetsException extends Exception {
        public NotEnoughWidgetsException(String message) {
            super(message);
        }
    }

    static class WidgetCount {
        private int count;

        public WidgetCount(int count) {
            this.count = count;
        }

        public int getCount() {
            return count;
        }

        public void setCount(int count) {
            this.count = count;
        }

        public void add(int amount) {
            this.count += amount;
        }

        public void subtract(int amount) {
            this.count -= amount;
        }
    }

    static class Bin {
        private final String name;
        private final WidgetCount widgetCount;
        private final ReentrantLock lock;

        public Bin(String name, int initialCount) {
            this.name = name;
            this.widgetCount = new WidgetCount(initialCount);
            this.lock = new ReentrantLock();
        }

        public String getName() {
            return name;
        }

        public WidgetCount getWidgetCount() {
            return widgetCount;
        }

        public ReentrantLock getLock() {
            return lock;
        }
    }

    public static boolean move(Bin sourceBin, Bin targetBin, int numberOfWidgets, 
                               long timeout, TimeUnit timeUnit) throws NotEnoughWidgetsException {
        long startTime = System.nanoTime();
        long timeoutNanos = timeUnit.toNanos(timeout);

        while (System.nanoTime() - startTime < timeoutNanos) {
            boolean sourceLocked = false;
            boolean targetLocked = false;

            try {
                long remainingTime = timeoutNanos - (System.nanoTime() - startTime);
                if (remainingTime <= 0) {
                    return false;
                }

                sourceLocked = sourceBin.getLock().tryLock(remainingTime, TimeUnit.NANOSECONDS);
                if (!sourceLocked) {
                    return false;
                }

                remainingTime = timeoutNanos - (System.nanoTime() - startTime);
                if (remainingTime <= 0) {
                    return false;
                }

                targetLocked = targetBin.getLock().tryLock(remainingTime, TimeUnit.NANOSECONDS);
                if (!targetLocked) {
                    Thread.sleep(getFixedDelay() + getRandomDelay());
                    continue;
                }

                if (sourceBin.getWidgetCount().getCount() < numberOfWidgets) {
                    throw new NotEnoughWidgetsException("Source bin does not have enough widgets");
                }

                sourceBin.getWidgetCount().subtract(numberOfWidgets);
                targetBin.getWidgetCount().add(numberOfWidgets);

                return true;

            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return false;
            } finally {
                if (targetLocked) {
                    targetBin.getLock().unlock();
                }
                if (sourceLocked) {
                    sourceBin.getLock().unlock();
                }
            }
        }

        return false;
    }

    private static long getFixedDelay() {
        return 10;
    }

    private static long getRandomDelay() {
        return random.nextInt(50);
    }

    public static void main(String[] args) {
        Bin bin1 = new Bin("Bin1", 100);
        Bin bin2 = new Bin("Bin2", 50);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> {
            for (int i = 0; i < 5; i++) {
                try {
                    boolean success = move(bin1, bin2, 10, 1, TimeUnit.SECONDS);
                    System.out.println("Thread 1 - Move " + (i + 1) + ": " + 
                        (success ? "Success" : "Failed") + 
                        " | Bin1: " + bin1.getWidgetCount().getCount() + 
                        ", Bin2: " + bin2.getWidgetCount().getCount());
                    Thread.sleep(100);
                } catch (NotEnoughWidgetsException e) {
                    System.out.println("Thread 1 - Move " + (i + 1) + ": " + e.getMessage());
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });

        executor.submit(() -> {
            for (int i = 0; i < 5; i++) {
                try {
                    boolean success = move(bin2, bin1, 5, 1, TimeUnit.SECONDS);
                    System.out.println("Thread 2 - Move " + (i + 1) + ": " + 
                        (success ? "Success" : "Failed") + 
                        " | Bin1: " + bin1.getWidgetCount().getCount() + 
                        ", Bin2: " + bin2.getWidgetCount().getCount());
                    Thread.sleep(150);
                } catch (NotEnoughWidgetsException e) {
                    System.out.println("Thread 2 - Move " + (i + 1) + ": " + e.getMessage());
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });

        executor.shutdown();
        try {
            executor.awaitTermination(10, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println("Final state - Bin1: " + bin1.getWidgetCount().getCount() + 
                          ", Bin2: " + bin2.getWidgetCount().getCount());
    }
}
