            for (int i = 0; i < 10; i++) {
                Person person = new PersonImpl("Person" + i, 20 + i);
                boolean exists = personSet.contains(person);
                System.out.println("Contains Person" + i + ": " + exists);
            }
            return null;
        });

        insertTask.get();
        checkTask.get();

        executor.shutdown();
