import java.util.*;

/**
* PersonSet
*
* A thread-safe set using synchronized methods,
* adapted to be compatible with Java Pathfinder (JPF).
*/
public class PersonSet {
private final Set<Person> mySet = new HashSet<>();

public synchronized void addPerson(Person p) {
mySet.add(p);
}

public synchronized boolean containsPerson(Person p) {
return mySet.contains(p);
}

public interface Person {
String getName();
}

public static class SimplePerson implements Person {
private final String name;

public SimplePerson(String name) {
this.name = name;
}

@Override
public String getName() {
return name;
}

@Override
public boolean equals(Object o) {
if (this == o) return true;
if (!(o instanceof SimplePerson)) return false;
SimplePerson that = (SimplePerson) o;
return Objects.equals(name, that.name);
}

@Override
public int hashCode() {
return Objects.hash(name);
}

@Override
public String toString() {
return "Person{name='" + name + "'}";
}
}

public static void main(String[] args) throws InterruptedException {
PersonSet personSet = new PersonSet();

Thread t1 = new Thread(() -> {
Person p = new SimplePerson("Alice");
personSet.addPerson(p);
System.out.println(Thread.currentThread().getName() + " added: " + p);
});

Thread t2 = new Thread(() -> {
Person p = new SimplePerson("Bob");
personSet.addPerson(p);
System.out.println(Thread.currentThread().getName() + " added: " + p);
});

t1.start();
t2.start();

t1.join();
t2.join();

List<String> checkNames = Arrays.asList("Alice", "Frank");
for (String name : checkNames) {
Person p = new SimplePerson(name);
System.out.println(p.getName() + " is in set? " + personSet.containsPerson(p));
}

System.out.println("Program completed.");
}
}

