import java.util.*;
import java.util.concurrent.*;

public class PersonSet {

    public interface Person {
        String getName();
        int getAge();
    }

    private final Set<Person> personSet;

    public PersonSet() {
        this.personSet = new HashSet<>();
    }

    public synchronized void register(Person person) {
        personSet.add(person);
    }

    public synchronized boolean contains(Person person) {
        return personSet.contains(person);
    }

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        PersonSet personSet = new PersonSet();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        Person person1 = new PersonImpl("Alice", 25);
        Person person2 = new PersonImpl("Bob", 30);
        Person person3 = new PersonImpl("Charlie", 35);

        Future<?> future1 = executor.submit(() -> {
            personSet.register(person1);
            personSet.register(person2);
            System.out.println("Thread 1: Registered Alice and Bob");
            System.out.println("Thread 1: Contains Alice? " + personSet.contains(person1));
        });

        Future<?> future2 = executor.submit(() -> {
            personSet.register(person3);
            System.out.println("Thread 2: Registered Charlie");
            System.out.println("Thread 2: Contains Bob? " + personSet.contains(person2));
            System.out.println("Thread 2: Contains Charlie? " + personSet.contains(person3));
        });

        future1.get();
        future2.get();

        System.out.println("Main thread: Contains Alice? " + personSet.contains(person1));
        System.out.println("Main thread: Contains Bob? " + personSet.contains(person2));
        System.out.println("Main thread: Contains Charlie? " + personSet.contains(person3));

        executor.shutdown();
    }
}

