import java.util.*;
import java.util.concurrent.*;

public class PublishingVehicleTracker {
    private final ConcurrentHashMap<String, SafePoint> locations;
    private final Map<String, SafePoint> unmodifiableMap;

    public PublishingVehicleTracker(Map<String, SafePoint> locations) {
        this.locations = new ConcurrentHashMap<>(locations);
        this.unmodifiableMap = Collections.unmodifiableMap(this.locations);
    }

    public Map<String, SafePoint> getLocations() {
        return unmodifiableMap;
    }

    public SafePoint getLocation(String id) {
        return locations.get(id);
    }

    public void setLocation(String id, int x, int y) {
        SafePoint loc = locations.get(id);
        if (loc == null) {
            throw new IllegalArgumentException("Vehicle not found: " + id);
        }
        loc.set(x, y);
    }

    public static void main(String[] args) throws InterruptedException {
        Map<String, SafePoint> initialLocations = new HashMap<>();
        initialLocations.put("vehicle1", new SafePoint(0, 0));
        initialLocations.put("vehicle2", new SafePoint(10, 10));
        initialLocations.put("vehicle3", new SafePoint(20, 20));

        PublishingVehicleTracker tracker = new PublishingVehicleTracker(initialLocations);
        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> {
            for (int i = 0; i < 5; i++) {
                tracker.setLocation("vehicle1", i * 2, i * 3);
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });

        executor.submit(() -> {
            for (int i = 0; i < 5; i++) {
                tracker.setLocation("vehicle2", i * 4, i * 5);
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });

        Thread.sleep(200);

        Map<String, SafePoint> locations = tracker.getLocations();
        for (Map.Entry<String, SafePoint> entry : locations.entrySet()) {
            SafePoint point = entry.getValue();
            System.out.println(entry.getKey() + ": [" + point.get()[0] + ", " + point.get()[1] + "]");
        }

        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.SECONDS);
    }
}

class SafePoint {
    private int x, y;

    public SafePoint(int x, int y) {
        this.set(x, y);
    }

    public SafePoint(SafePoint p) {
        this(p.get());
    }

    public SafePoint(int[] a) {
        this(a[0], a[1]);
    }

    public synchronized int[] get() {
        return new int[]{x, y};
    }

    public synchronized void set(int x, int y) {
        this.x = x;
        this.y = y;
    }
}

