this.locations = new ConcurrentHashMap<>(locations);
this.unmodifiableMap = Collections.unmodifiableMap(this.locations);
}

public Map<String, SafePoint> getLocations() {
return unmodifiableMap;
}

public SafePoint getLocation(String id) {
return locations.get(id);
}

public void setLocation(String id, int x, int y) {
if (!locations.containsKey(id))
throw new IllegalArgumentException("invalid vehicle name: " + id);
locations.get(id).set(x, y);
}

public static void main(String[] args) throws InterruptedException {
Map<String, SafePoint> initialPoints = new HashMap<>();
initialPoints.put("V1", new SafePoint(0, 0));
initialPoints.put("V2", new SafePoint(10, 10));
initialPoints.put("V3", new SafePoint(20, 20));

PublishingVehicleTracker tracker = new PublishingVehicleTracker(initialPoints);

Thread[] threads = new Thread[2]; // fewer threads for faster JPF testing

for (int i = 0; i < 2; i++) {
final int taskId = i;
threads[i] = new Thread(() -> {
Random rand = new Random();
for (int j = 0; j < 3; j++) { // fewer iterations
String vehicleId = "V" + ((taskId % 3) + 1);
int newX = rand.nextInt(6); // 0 to 5
int newY = rand.nextInt(6); // 0 to 5
tracker.setLocation(vehicleId, newX, newY);
System.out.println(Thread.currentThread().getName() +
" updated " + vehicleId + " to (" + newX + ", " + newY + ")");
try {
Thread.sleep(20); // shorter sleep
} catch (InterruptedException e) {
Thread.currentThread().interrupt();
}
}
});
}

for (Thread t : threads) {
t.start();
}

for (Thread t : threads) {
t.join();
}

System.out.println("\nFinal vehicle locations:");
tracker.getLocations().forEach((id, point) ->
System.out.println(id + ": (" + point.getX() + ", " + point.getY() + ")"));
}
}

