class RuneChanneler {
    private final ExecutorService executor = Executors.newFixedThreadPool(2);

    public int channelTheGrimoire(Collection<Rune> candidateRunes) throws InterruptedException, ExecutionException {
        List<Rune> localRunes = new ArrayList<>(candidateRunes);

        Comparator<Rune> runeComparator = Comparator
            .comparing(Rune::getConstellation)
            .thenComparing(Rune::getResonance);

        localRunes.sort(runeComparator);

        Grimoire grimoire = new Grimoire();

        int midPoint = localRunes.size() / 2;
        List<Rune> firstHalf = localRunes.subList(0, midPoint);
        List<Rune> secondHalf = localRunes.subList(midPoint, localRunes.size());

        Future<Integer> task1 = executor.submit(() -> {
            int count = 0;
            for (int i = 0; i < firstHalf.size(); i++) {
                for (int j = i + 1; j < localRunes.size(); j++) {
                    Rune rune1 = firstHalf.get(i);
                    Rune rune2 = localRunes.get(j);
                    if (rune1.canHarmonizeWith(rune2)) {
                        grimoire.crystallize(new RuneHarmony(rune1, rune2));
                        count++;
                    }
                }
            }
            return count;
        });

        Future<Integer> task2 = executor.submit(() -> {
            int count = 0;
            for (int i = 0; i < secondHalf.size(); i++) {
                for (int j = i + 1; j < secondHalf.size(); j++) {
