class Grimoire {
    private final List<RuneHarmony> harmonies = Collections.synchronizedList(new ArrayList<>());
    private final ExecutorService executor = Executors.newFixedThreadPool(2);

    public int channelTheGrimoire(Collection<Rune> candidateRunes) throws InterruptedException, ExecutionException {
        List<Rune> transmutedRunes = new ArrayList<>(candidateRunes);

        Comparator<Rune> runeComparator = Comparator
            .comparing(Rune::getConstellation)
            .thenComparing(Rune::getResonance);

        Collections.sort(transmutedRunes, runeComparator);

        Map<Constellation, List<Rune>> constellationGroups = transmutedRunes.stream()
            .collect(Collectors.groupingBy(Rune::getConstellation));

        List<Future<Integer>> futures = new ArrayList<>();

        for (Map.Entry<Constellation, List<Rune>> entry : constellationGroups.entrySet()) {
            futures.add(executor.submit(() -> {
                int localHarmonies = 0;
                List<Rune> runeGroup = new ArrayList<>(entry.getValue());
                List<Rune> lightRunes = runeGroup.stream()
                    .filter(r -> r.getResonance() == Resonance.LIGHT)
                    .collect(Collectors.toList());
                List<Rune> darkRunes = runeGroup.stream()
                    .filter(r -> r.getResonance() == Resonance.DARK)
                    .collect(Collectors.toList());

                int pairs = Math.min(lightRunes.size(), darkRunes.size());

                for (int i = 0; i < pairs; i++) {
                    RuneHarmony harmony = new RuneHarmony(lightRunes.get(i), darkRunes.get(i));
                    harmonies.add(harmony);
                    localHarmonies++;
                }

                return localHarmonies;
            }));
        }

        int totalHarmonies = 0;
        for (Future<Integer> future : futures) {
            totalHarmonies += future.get();
        }

        return totalHarmonies;
    }

    public void crystallizeHarmonies() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }

        synchronized (harmonies) {
            System.out.println("Crystallized Harmonies:");
            for (RuneHarmony harmony : harmonies) {
                System.out.println(harmony);
            }
        }
    }
}

