    public int channelTheGrimoire(Collection<Rune> candidateRunes) {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        List<Rune> transmutedRunes = new ArrayList<>(candidateRunes);

        transmutedRunes.sort(new RuneComparator());

        Map<Constellation, List<Rune>> runesByConstellation = new ConcurrentHashMap<>();
        for (Rune rune : transmutedRunes) {
            runesByConstellation.computeIfAbsent(rune.getConstellation(), k -> new CopyOnWriteArrayList<>()).add(rune);
        }

        List<Future<List<Harmony>>> futures = new ArrayList<>();

        for (Map.Entry<Constellation, List<Rune>> entry : runesByConstellation.entrySet()) {
            Future<List<Harmony>> future = executor.submit(() -> {
                List<Harmony> localHarmonies = new ArrayList<>();
                List<Rune> constellationRunes = new ArrayList<>(entry.getValue());
                List<Rune> lightRunes = constellationRunes.stream()
                    .filter(r -> r.getResonance() == Resonance.LIGHT)
                    .collect(Collectors.toList());
                List<Rune> darkRunes = constellationRunes.stream()
                    .filter(r -> r.getResonance() == Resonance.DARK)
                    .collect(Collectors.toList());

                int pairs = Math.min(lightRunes.size(), darkRunes.size());
                for (int i = 0; i < pairs; i++) {
                    localHarmonies.add(new Harmony(lightRunes.get(i), darkRunes.get(i)));
                }
                return localHarmonies;
            });
            futures.add(future);
        }

        List<Harmony> allHarmonies = new ArrayList<>();
        for (Future<List<Harmony>> future : futures) {
            try {
                allHarmonies.addAll(future.get());
            } catch (InterruptedException | ExecutionException e) {
                Thread.currentThread().interrupt();
            }
        }

        executor.shutdown();
        try {
            executor.awaitTermination(10, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        Grimoire grimoire = new Grimoire();
        grimoire.crystallize(allHarmonies);

        return allHarmonies.size();
    }

    class RuneComparator implements Comparator<Rune> {
        @Override
        public int compare(Rune r1, Rune r2) {
            int constellationCompare = r1.getConstellation().compareTo(r2.getConstellation());
            if (constellationCompare != 0) {
                return constellationCompare;
            }
            return r1.getResonance().compareTo(r2.getResonance());
        }
    }
