    }
}

public class MysticBeastTracker {
    private final ConcurrentHashMap<String, Glyph> beastPerches;

    public MysticBeastTracker(Map<String, Glyph> initialPerches) {
        this.beastPerches = new ConcurrentHashMap<>(initialPerches);
    }

    public Map<String, Glyph> getPerches() {
        return Collections.unmodifiableMap(beastPerches);
    }

    public Glyph getPerch(String sigil) {
        return beastPerches.get(sigil);
    }

    public void setPerch(String sigil, int spark, int glimmer) {
        Glyph newGlyph = new Glyph(spark, glimmer);
        Glyph oldGlyph = beastPerches.replace(sigil, newGlyph);
        if (oldGlyph == null) {
            throw new IllegalArgumentException("Beast with sigil '" + sigil + "' does not exist");
        }
    }

    public Map<String, Glyph> getPerchesAsStatic() {
        return Collections.unmodifiableMap(new HashMap<>(beastPerches));
    }

    public static void main(String[] args) throws InterruptedException {
        Map<String, Glyph> initialPerches = new HashMap<>();
        initialPerches.put("Phoenix", new Glyph(100, 200));
        initialPerches.put("Dragon", new Glyph(150, 250));
        initialPerches.put("Griffin", new Glyph(75, 125));
        initialPerches.put("Pegasus", new Glyph(90, 180));
        initialPerches.put("Thunderbird", new Glyph(110, 220));

        MysticBeastTracker tracker = new MysticBeastTracker(initialPerches);
        ExecutorService executor = Executors.newFixedThreadPool(5);
        CountDownLatch latch = new CountDownLatch(5);

        executor.submit(() -> {
            try {
                for (int i = 0; i < 10; i++) {
                    tracker.setPerch("Phoenix", 100 + i * 10, 200 + i * 10);
                    Thread.sleep(50);
                }
