                e.printStackTrace();
            } finally {
                latch.countDown();
            }
        });

        executor.submit(() -> {
            try {
                for (int i = 0; i < 10; i++) {
                    tracker.setPerch("Dragon", 150 - i * 5, 250 - i * 5);
                    Thread.sleep(60);
                }
            } catch (Exception e) {
                e.printStackTrace();
            } finally {
                latch.countDown();
            }
        });

        executor.submit(() -> {
            try {
                for (int i = 0; i < 8; i++) {
                    Glyph perch = tracker.getPerch("Griffin");
                    if (perch != null) {
                        System.out.println("Griffin at: " + perch);
                    }
                    Thread.sleep(70);
                }
            } catch (Exception e) {
                e.printStackTrace();
            } finally {
                latch.countDown();
            }
        });

        executor.submit(() -> {
            try {
                for (int i = 0; i < 5; i++) {
                    Map<String, Glyph> snapshot = tracker.getPerchesAsStatic();
                    System.out.println("Snapshot " + i + ": " + snapshot.size() + " beasts");
                    Thread.sleep(100);
                }
            } catch (Exception e) {
                e.printStackTrace();
            } finally {
                latch.countDown();
            }
        });

        executor.submit(() -> {
            try {
                for (int i = 0; i < 10; i++) {
                    tracker.setPerch("Pegasus", 90 + i * 15, 180 + i * 15);
