import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;

interface Talisman {
    String enchant();
}

interface SigilNode {
    int compute();
    List<SigilNode> getChildren();
}

class SimpleTalisman implements Talisman {
    private final String name;

    public SimpleTalisman(String name) {
        this.name = name;
    }

    public String enchant() {
        try {
            Thread.sleep(100);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return "Enchanted-" + name;
    }
}

class SimpleSigilNode implements SigilNode {
    private final int value;
    private final List<SigilNode> children;

    public SimpleSigilNode(int value, List<SigilNode> children) {
        this.value = value;
        this.children = new ArrayList<>(children);
    }

    public int compute() {
        try {
            Thread.sleep(50);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return value * 2;
    }

    public List<SigilNode> getChildren() {
        return new ArrayList<>(children);
    }
}

class EnchantmentProcessor {
    private final ExecutorService executor;

    public EnchantmentProcessor() {
        this.executor = Executors.newFixedThreadPool(2);
    }

    public List<String> weaveSequential(List<Talisman> talismans) {
        List<String> results = new ArrayList<>();
        for (Talisman talisman : talismans) {
            results.add(talisman.enchant());
        }
        return results;
    }

    public List<String> weaveParallel(List<Talisman> talismans) {
        List<Future<String>> futures = new ArrayList<>();
        for (Talisman talisman : talismans) {
            futures.add(executor.submit(talisman::enchant));
        }

        List<String> results = new ArrayList<>();
        for (Future<String> future : futures) {
            try {
                results.add(future.get());
            } catch (InterruptedException | ExecutionException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException(e);
            }
        }
        return results;
    }

    public List<Integer> traverseSequential(SigilNode root) {
        List<Integer> results = new ArrayList<>();
        traverseSequentialHelper(root, results);
        return results;
    }

    private void traverseSequentialHelper(SigilNode node, List<Integer> results) {
        if (node == null) return;
        results.add(node.compute());
        for (SigilNode child : node.getChildren()) {
            traverseSequentialHelper(child, results);
        }
    }

    public List<Integer> traverseParallel(SigilNode root) {
        ConcurrentLinkedQueue<Integer> results = new ConcurrentLinkedQueue<>();
        CountDownLatch latch = traverseParallelHelper(root, results);
        try {
            latch.await();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new RuntimeException(e);
        }
        return new ArrayList<>(results);
    }

    private CountDownLatch traverseParallelHelper(SigilNode node, ConcurrentLinkedQueue<Integer> results) {
        if (node == null) return new CountDownLatch(0);

        List<SigilNode> children = node.getChildren();
        CountDownLatch latch = new CountDownLatch(1 + children.size());

        executor.submit(() -> {
            try {
                results.add(node.compute());
            } finally {
                latch.countDown();
            }
        });

        for (SigilNode child : children) {
            executor.submit(() -> {
                try {
                    CountDownLatch childLatch = traverseParallelHelper(child, results);
                    childLatch.await();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                } finally {
                    latch.countDown();
                }
            });
        }

        return latch;
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }
}

public class ConcurrentEnchantment {
    public static void main(String[] args) {
        EnchantmentProcessor processor = new EnchantmentProcessor();

        List<Talisman> talismans = Arrays.asList(
            new SimpleTalisman("Alpha"),
            new SimpleTalisman("Beta"),
            new SimpleTalisman("Gamma"),
            new SimpleTalisman("Delta")
        );

        System.out.println("Sequential Talisman Enchantment:");
        long startTime = System.currentTimeMillis();
        List<String> seqResults = processor.weaveSequential(talismans);
        long seqTime = System.currentTimeMillis() - startTime;
        seqResults.forEach(System.out::println);
        System.out.println("Sequential time: " + seqTime + "ms\n");

        System.out.println("Parallel Talisman Enchantment:");
        startTime = System.currentTimeMillis();
        List<String> parResults = processor.weaveParallel(talismans);
        long parTime = System.currentTimeMillis() - startTime;
        parResults.forEach(System.out::println);
        System.out.println("Parallel time: " + parTime + "ms\n");

        SigilNode root = new SimpleSigilNode(1, Arrays.asList(
            new SimpleSigilNode(2, Arrays.asList(
                new SimpleSigilNode(4, Collections.emptyList()),
                new SimpleSigilNode(5, Collections.emptyList())
            )),
            new SimpleSigilNode(3, Arrays.asList(
                new SimpleSigilNode(6, Collections.emptyList()),
                new SimpleSigilNode(7, Collections.emptyList())
            ))
        ));

        System.out.println("Sequential Sigil Traversal:");
        startTime = System.currentTimeMillis();
        List<Integer> seqSigilResults = processor.traverseSequential(root);
        long seqSigilTime = System.currentTimeMillis() - startTime;
        System.out.println(seqSigilResults);
        System.out.println("Sequential sigil time: " + seqSigilTime + "ms\n");

        System.out.println("Parallel Sigil Traversal:");
        startTime = System.currentTimeMillis();
        List<Integer> parSigilResults = processor.traverseParallel(root);
        long parSigilTime = System.currentTimeMillis() - startTime;
        System.out.println(parSigilResults);
        System.out.println("Parallel sigil time: " + parSigilTime + "ms");

        processor.shutdown();
    }
}

