import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

interface GoldAmount {
    long getAmount();
}

interface Vault {
    void debit(GoldAmount amount) throws InsufficientTreasureException;
    void credit(GoldAmount amount);
    GoldAmount getBalance();
}

class InsufficientTreasureException extends Exception {
    public InsufficientTreasureException(String message) {
        super(message);
    }
}

class Gold implements GoldAmount {
    private final long amount;

    public Gold(long amount) {
        this.amount = amount;
    }

    @Override
    public long getAmount() {
        return amount;
    }
}

class TreasureVault implements Vault {
    private long balance;
    private final String name;

    public TreasureVault(String name, long initialBalance) {
        this.name = name;
        this.balance = initialBalance;
    }

    @Override
    public void debit(GoldAmount amount) throws InsufficientTreasureException {
        if (balance < amount.getAmount()) {
            throw new InsufficientTreasureException("Insufficient treasure in vault " + name);
        }
        balance -= amount.getAmount();
    }

    @Override
    public void credit(GoldAmount amount) {
        balance += amount.getAmount();
    }

    @Override
    public GoldAmount getBalance() {
