    }

    public String getName() {
        return name;
    }
}

class TransferHelper {
    private static final Lock tieBreakerLock = new ReentrantLock();

    public static void transfer(Vault fromVault, Vault toVault, GoldAmount amount) 
            throws InsufficientTreasureException {
        int fromHash = System.identityHashCode(fromVault);
        int toHash = System.identityHashCode(toVault);

        if (fromHash < toHash) {
            synchronized (fromVault) {
                synchronized (toVault) {
                    performTransfer(fromVault, toVault, amount);
                }
            }
        } else if (fromHash > toHash) {
            synchronized (toVault) {
                synchronized (fromVault) {
                    performTransfer(fromVault, toVault, amount);
                }
            }
        } else {
            tieBreakerLock.lock();
            try {
                synchronized (fromVault) {
                    synchronized (toVault) {
                        performTransfer(fromVault, toVault, amount);
                    }
                }
            } finally {
                tieBreakerLock.unlock();
            }
        }
    }

    private static void performTransfer(Vault fromVault, Vault toVault, GoldAmount amount) 
            throws InsufficientTreasureException {
        fromVault.debit(amount);
        toVault.credit(amount);
    }
}

