class Orb {
    private final int id;
    private final String type;

    public Orb(int id, String type) {
        this.id = id;
        this.type = type;
    }

    @Override
    public String toString() {
        return "Orb{id=" + id + ", type='" + type + "'}";
    }
}

class MagicalOrbVault {
    private final int capacity;
    private final Queue<Orb> vault;
    private final Semaphore availableOrbs;
    private final Semaphore availableSlots;
    private final Object lock = new Object();

    public MagicalOrbVault(int capacity) {
        this.capacity = capacity;
        this.vault = new LinkedList<>();
        this.availableOrbs = new Semaphore(0);
        this.availableSlots = new Semaphore(capacity);
    }

    public void put(Orb orb) throws InterruptedException {
        availableSlots.acquire();
        synchronized (lock) {
            vault.offer(orb);
        }
        availableOrbs.release();
    }

    public Orb take() throws InterruptedException {
        availableOrbs.acquire();
        Orb orb;
        synchronized (lock) {
            orb = vault.poll();
        }
        availableSlots.release();
        return orb;
    }

    public boolean isEmpty() {
        synchronized (lock) {
            return vault.isEmpty();
        }
    }

    public boolean isFull() {
        synchronized (lock) {
            return vault.size() == capacity;
        }
    }
}

