        this.name = name;
        this.strength = strength;
    }

    @Override
    public String toString() {
        return name + " (strength: " + strength + ")";
    }
}

class PotionLoop {
    private final Potion[] buffer;
    private final int capacity;
    private int head;
    private int tail;
    private int count;
    private final Semaphore available;
    private final Semaphore spaces;
    private final Object lock;

    public PotionLoop(int capacity) {
        this.capacity = capacity;
        this.buffer = new Potion[capacity];
        this.head = 0;
        this.tail = 0;
        this.count = 0;
        this.available = new Semaphore(0);
        this.spaces = new Semaphore(capacity);
        this.lock = new Object();
    }

    public void put(Potion x) throws InterruptedException {
        spaces.acquire();
        synchronized (lock) {
            buffer[tail] = x;
            tail = (tail + 1) % capacity;
            count++;
        }
        available.release();
    }

    public Potion take() throws InterruptedException {
        available.acquire();
        Potion potion;
        synchronized (lock) {
            potion = buffer[head];
            buffer[head] = null;
            head = (head + 1) % capacity;
            count--;
        }
        spaces.release();
        return potion;
    }

    public boolean isEmpty() {
        synchronized (lock) {
            return count == 0;
        }
    }

    public boolean isFull() {
        synchronized (lock) {
            return count == capacity;
        }
    }
}

