import java.util.*;

public class MonitorVehicleTracker {
private final Map<String, MutablePoint> locations;

public MonitorVehicleTracker(Map<String, MutablePoint> locations) {
this.locations = deepCopy(locations);
}

public synchronized Map<String, MutablePoint> getLocations() {
return deepCopy(locations);
}

public synchronized MutablePoint getLocation(String id) {
MutablePoint loc = locations.get(id);
return loc == null ? null : new MutablePoint(loc);
}

public synchronized void setLocation(String id, int x, int y) {
MutablePoint loc = locations.get(id);
if (loc == null)
throw new IllegalArgumentException("No such ID: " + id);
loc.x = x;
loc.y = y;
}

private static Map<String, MutablePoint> deepCopy(Map<String, MutablePoint> m) {
Map<String, MutablePoint> result = new HashMap<>();
for (String id : m.keySet())
result.put(id, new MutablePoint(m.get(id)));
return Collections.unmodifiableMap(result);
}

public static void main(String[] args) throws InterruptedException {
Map<String, MutablePoint> initialLocations = new HashMap<>();
initialLocations.put("car1", new MutablePoint(0, 0));
initialLocations.put("car2", new MutablePoint(10, 10));

MonitorVehicleTracker tracker = new MonitorVehicleTracker(initialLocations);

Thread updater = new Thread(() -> {
try {
Thread.sleep(500);
tracker.setLocation("car1", 5, 5);
System.out.println("Updated car1 to (5,5)");
} catch (Exception e) {
e.printStackTrace();
}
});

Thread reader = new Thread(() -> {
try {
Thread.sleep(1000);
Map<String, MutablePoint> snapshot = tracker.getLocations();
System.out.println("Current locations:");
snapshot.forEach((id, point) -> System.out.println(id + ": (" + point.x + ", " + point.y + ")"));
} catch (Exception e) {
e.printStackTrace();
}
});

updater.start();
reader.start();

updater.join();
reader.join();

System.out.println("All threads completed.");
}
}

