            threads[i] = new FluxThread();
            threads[i].start();
        }

        for (FluxThread thread : threads) {
            try {
                thread.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        System.out.println("Energy swaps completed.");
        for (int i = 0; i < NUM_ORBS; i++) {
            System.out.println("Orb " + i + ": " + orbs[i].getEnergy());
        }
