import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class CelestialHourglass implements Runnable {
    private boolean activated;
    private long dawnTime;
    private long duskTime;

    public CelestialHourglass() {
        this.activated = false;
        this.dawnTime = 0;
        this.duskTime = 0;
    }

    @Override
    public synchronized void run() {
        long currentTime = System.nanoTime();
        if (!activated) {
            activated = true;
            dawnTime = currentTime;
        } else {
            duskTime = currentTime;
        }
    }

    public synchronized void reset() {
        activated = false;
    }

    public synchronized long getFlow() {
        return duskTime - dawnTime;
    }

    public static void main(String[] args) {
        CelestialHourglass hourglass = new CelestialHourglass();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> {
            hourglass.run();
            try {
                Thread.sleep(100);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            hourglass.run();
        });

        executor.submit(() -> {
            try {
                Thread.sleep(50);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            hourglass.run();
            try {
                Thread.sleep(100);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            hourglass.run();
        });

        try {
            Thread.sleep(300);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println("Flow: " + hourglass.getFlow());

        hourglass.reset();

        executor.submit(hourglass);
        executor.submit(hourglass);

        executor.shutdown();
        try {
            executor.awaitTermination(1, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println("Final Flow: " + hourglass.getFlow());
    }
}

