import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class MysticWatcher {
    private final ArcaneSource source;
    private final ExecutorService executor = Executors.newSingleThreadExecutor();

    private MysticWatcher(ArcaneSource source) {
        this.source = source;
    }

    public static MysticWatcher summonInstance(ArcaneSource source) {
        MysticWatcher watcher = new MysticWatcher(source);
        ArcaneListener listener = new ArcaneListener() {
            @Override
            public void onMysticEvent(MysticEvent event) {
                watcher.executor.execute(() -> watcher.castSpell());
            }
        };
        source.registerListener(listener);
        return watcher;
    }

    private synchronized void castSpell() {
        System.out.println("Casting spell on thread: " + Thread.currentThread().getName());
    }

    public void shutdown() {
        executor.shutdown();
        try {
            executor.awaitTermination(5, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public static void main(String[] args) {
        ArcaneSource source = new ArcaneSourceImpl();
        MysticWatcher watcher = MysticWatcher.summonInstance(source);

        for (int i = 0; i < 5; i++) {
            source.triggerEvent(new MysticEventImpl());
            try {
                Thread.sleep(100);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        watcher.shutdown();
    }
