import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.ReentrantLock;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.Random;

public class DeadlockAvoidanceTransfer {

   static class DollarAmount {
       private final long cents;

       public DollarAmount(double dollars) {
           this.cents = Math.round(dollars * 100);
       }

       public DollarAmount(long cents) {
           this.cents = cents;
       }

       public long getCents() {
           return cents;
       }

       public double getDollars() {
           return cents / 100.0;
       }

       public DollarAmount add(DollarAmount other) {
           return new DollarAmount(this.cents + other.cents);
       }

       public DollarAmount subtract(DollarAmount other) {
           return new DollarAmount(this.cents - other.cents);
       }

       public boolean isGreaterThanOrEqual(DollarAmount other) {
           return this.cents >= other.cents;
       }

       public String toString() {
           return String.format("$%.2f", getDollars());
       }
   }

   static class Account {
       private final int id;
       private DollarAmount balance;
       private final ReentrantLock lock;

       public Account(int id, DollarAmount initialBalance) {
           this.id = id;
           this.balance = initialBalance;
           this.lock = new ReentrantLock();
       }

       public int getId() {
           return id;
       }

       public DollarAmount getBalance() {
           return balance;
       }

       public void setBalance(DollarAmount balance) {
           this.balance = balance;
       }

       public ReentrantLock getLock() {
           return lock;
       }

       public String toString() {
           return String.format("Account[id=%d, balance=%s]", id, balance);
       }
   }

   static class InsufficientFundsException extends Exception {
       public InsufficientFundsException(String message) {
           super(message);
       }
   }

   private static final Random random = new Random();

   public static boolean transferMoney(Account source, Account destination, DollarAmount amount, 
                                     long timeout, TimeUnit unit) throws InsufficientFundsException {
       long timeoutMillis = unit.toMillis(timeout);
       long startTime = System.currentTimeMillis();
       int maxRetries = 3;
       int retryCount = 0;

       while (retryCount < maxRetries && (System.currentTimeMillis() - startTime) < timeoutMillis) {
           Account firstLock = source.getId() < destination.getId() ? source : destination;
           Account secondLock = source.getId() < destination.getId() ? destination : source;

           try {
               boolean firstAcquired = firstLock.getLock().tryLock(50, TimeUnit.MILLISECONDS);
               if (!firstAcquired) {
                   retryCount++;
                   Thread.sleep(calculateDelay());
                   continue;
               }

               try {
                   boolean secondAcquired = secondLock.getLock().tryLock(50, TimeUnit.MILLISECONDS);
                   if (!secondAcquired) {
                       retryCount++;
                       Thread.sleep(calculateDelay());
                       continue;
                   }

                   try {
                       if (!source.getBalance().isGreaterThanOrEqual(amount)) {
                           throw new InsufficientFundsException(
                               String.format("Insufficient funds in account %d", source.getId()));
                       }

                       source.setBalance(source.getBalance().subtract(amount));
                       destination.setBalance(destination.getBalance().add(amount));
                       return true;

                   } finally {
                       secondLock.getLock().unlock();
                   }
               } finally {
                   firstLock.getLock().unlock();
               }
           } catch (InterruptedException e) {
               Thread.currentThread().interrupt();
               return false;
           }
       }

       return false;
   }

   private static long calculateDelay() {
       return calculateFixedDelay() + calculateRandomDelay();
   }

   private static long calculateFixedDelay() {
       return 5;
   }

   private static long calculateRandomDelay() {
       return random.nextInt(10);
   }

   public static void main(String[] args) {
       Account account1 = new Account(1, new DollarAmount(1000.0));
       Account account2 = new Account(2, new DollarAmount(500.0));

       ExecutorService executor = Executors.newFixedThreadPool(2);

       System.out.println("Initial: A1=" + account1.getBalance() + " A2=" + account2.getBalance());

       Future<?> transfer1 = executor.submit(() -> {
           try {
               boolean success = transferMoney(account1, account2, new DollarAmount(200.0), 1, TimeUnit.SECONDS);
               System.out.println("T1: " + success);
           } catch (InsufficientFundsException e) {
               System.out.println("T1: FAILED");
           }
       });

