import java.math.BigInteger;
import java.util.Arrays;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class CachingServlet {

    private volatile OneValueCache cache = new OneValueCache(null, null);

    public void service(ServletRequest req, ServletResponse resp) {
        BigInteger i = extractFromRequest(req);
        BigInteger[] factors = cache.getFactors(i);
        if (factors == null) {
            factors = factor(i);
            cache = new OneValueCache(i, factors);
        }
        encodeIntoResponse(resp, factors);
    }

    private BigInteger extractFromRequest(ServletRequest req) {
        return req.getValue();
    }

    private void encodeIntoResponse(ServletResponse resp, BigInteger[] factors) {
        resp.setResult(factors);
    }

    private BigInteger[] factor(BigInteger i) {
        return new BigInteger[] { i };
    }

    public static void main(String[] args) {
        CachingServlet servlet = new CachingServlet();
        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> {
            ServletRequest req1 = new ServletRequest(new BigInteger("100"));
            ServletResponse resp1 = new ServletResponse();
            servlet.service(req1, resp1);
            System.out.println("Thread 1: " + Arrays.toString(resp1.getResult()));

            ServletRequest req2 = new ServletRequest(new BigInteger("100"));
            ServletResponse resp2 = new ServletResponse();
            servlet.service(req2, resp2);
            System.out.println("Thread 1 (cached): " + Arrays.toString(resp2.getResult()));
        });

        executor.submit(() -> {
            ServletRequest req1 = new ServletRequest(new BigInteger("200"));
            ServletResponse resp1 = new ServletResponse();
            servlet.service(req1, resp1);
            System.out.println("Thread 2: " + Arrays.toString(resp1.getResult()));

            ServletRequest req2 = new ServletRequest(new BigInteger("200"));
            ServletResponse resp2 = new ServletResponse();
            servlet.service(req2, resp2);
            System.out.println("Thread 2 (cached): " + Arrays.toString(resp2.getResult()));
        });

        executor.shutdown();
        try {
            executor.awaitTermination(5, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

class OneValueCache {
    private final BigInteger lastNumber;
    private final BigInteger[] lastFactors;

    public OneValueCache(BigInteger i, BigInteger[] factors) {
        lastNumber = i;
        lastFactors = factors == null ? null : Arrays.copyOf(factors, factors.length);
    }

    public BigInteger[] getFactors(BigInteger i) {
        if (lastNumber == null || !lastNumber.equals(i))
            return null;
        else
            return Arrays.copyOf(lastFactors, lastFactors.length);
    }
}

