public final class ThreeStooges {
    private final Set<String> stooges;
    private final List<String> stoogeList;

    public ThreeStooges() {
        List<String> names = Arrays.asList("Moe", "Larry", "Curly");
        this.stoogeList = Collections.unmodifiableList(names);
        this.stooges = Collections.unmodifiableSet(new HashSet<>(names));
    }

