import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class MyAppThread extends Thread {
    private static final String DEFAULT_NAME = "MyAppThread";
    private static final AtomicInteger threadNumber = new AtomicInteger(0);
    private static final Logger logger = Logger.getLogger(MyAppThread.class.getName());
    private static volatile boolean debugLifecycle = false;
    private static final AtomicInteger created = new AtomicInteger(0);
    private static final AtomicInteger alive = new AtomicInteger(0);

    public MyAppThread() {
        this(null);
    }

    public MyAppThread(Runnable target) {
        super(target, DEFAULT_NAME + "-" + threadNumber.incrementAndGet());
        setUncaughtExceptionHandler(new Thread.UncaughtExceptionHandler() {
            @Override
            public void uncaughtException(Thread t, Throwable e) {
                logger.log(Level.SEVERE, "Thread " + t.getName() + " died with exception", e);
            }
        });
    }

    @Override
    public void run() {
        created.incrementAndGet();
        alive.incrementAndGet();

        if (debugLifecycle) {
            logger.log(Level.INFO, "Created " + getName());
        }

        try {
            super.run();
        } finally {
            alive.decrementAndGet();
            if (debugLifecycle) {
                logger.log(Level.INFO, "Terminating " + getName());
            }
        }
    }

    public static int getCreated() {
