import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

interface DollarAmount {
    long getAmount();
}

interface Account {
    void debit(DollarAmount amount) throws InsufficientFundsException;
    void credit(DollarAmount amount);
    DollarAmount getBalance();
}

class InsufficientFundsException extends Exception {
    public InsufficientFundsException(String message) {
        super(message);
    }
}

class DollarAmountImpl implements DollarAmount {
    private final long amount;

    public DollarAmountImpl(long amount) {
        this.amount = amount;
    }

    public long getAmount() {
        return amount;
    }
}

class AccountImpl implements Account {
    private long balance;
    private final Lock lock = new ReentrantLock();

    public AccountImpl(long initialBalance) {
        this.balance = initialBalance;
    }

    public void debit(DollarAmount amount) throws InsufficientFundsException {
        if (balance < amount.getAmount()) {
            throw new InsufficientFundsException("Insufficient funds");
        }
        balance -= amount.getAmount();
    }

    public void credit(DollarAmount amount) {
        balance += amount.getAmount();
    }

    public DollarAmount getBalance() {
        return new DollarAmountImpl(balance);
    }

    public Lock getLock() {
        return lock;
    }
}

class TransferHelper {
    private static final Lock tieLock = new ReentrantLock();

    public static void transfer(AccountImpl fromAccount, AccountImpl toAccount, DollarAmount amount) 
            throws InsufficientFundsException {
        int fromHash = System.identityHashCode(fromAccount);
        int toHash = System.identityHashCode(toAccount);

        if (fromHash < toHash) {
            fromAccount.getLock().lock();
            try {
                toAccount.getLock().lock();
                try {
                    doTransfer(fromAccount, toAccount, amount);
                } finally {
                    toAccount.getLock().unlock();
                }
            } finally {
                fromAccount.getLock().unlock();
            }
        } else if (fromHash > toHash) {
            toAccount.getLock().lock();
            try {
                fromAccount.getLock().lock();
                try {
                    doTransfer(fromAccount, toAccount, amount);
                } finally {
                    fromAccount.getLock().unlock();
                }
            } finally {
                toAccount.getLock().unlock();
            }
        } else {
            tieLock.lock();
            try {
                fromAccount.getLock().lock();
                try {
                    toAccount.getLock().lock();
                    try {
                        doTransfer(fromAccount, toAccount, amount);
                    } finally {
                        toAccount.getLock().unlock();
                    }
                } finally {
                    fromAccount.getLock().unlock();
                }
            } finally {
                tieLock.unlock();
            }
        }
    }

    private static void doTransfer(AccountImpl fromAccount, AccountImpl toAccount, DollarAmount amount) 
            throws InsufficientFundsException {
        fromAccount.debit(amount);
        toAccount.credit(amount);
    }
}

public class MoneyTransferProgram {
    public static void main(String[] args) {
        AccountImpl account1 = new AccountImpl(1000);
        AccountImpl account2 = new AccountImpl(500);

        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> {
            try {
                for (int i = 0; i < 5; i++) {
                    TransferHelper.transfer(account1, account2, new DollarAmountImpl(100));
                    System.out.println("Transfer 1->2 completed. Balance 1: " + 
                        account1.getBalance().getAmount() + ", Balance 2: " + 
                        account2.getBalance().getAmount());
                    Thread.sleep(100);
                }
            } catch (InsufficientFundsException | InterruptedException e) {
                System.out.println("Transfer failed: " + e.getMessage());
            }
        });

        executor.submit(() -> {
            try {
                for (int i = 0; i < 3; i++) {
                    TransferHelper.transfer(account2, account1, new DollarAmountImpl(50));
                    System.out.println("Transfer 2->1 completed. Balance 1: " + 
                        account1.getBalance().getAmount() + ", Balance 2: " + 
                        account2.getBalance().getAmount());
                    Thread.sleep(150);
                }
            } catch (InsufficientFundsException | InterruptedException e) {
                System.out.println("Transfer failed: " + e.getMessage());
            }
        });

        executor.shutdown();
        try {
            executor.awaitTermination(5, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        System.out.println("Final Balance 1: " + account1.getBalance().getAmount());
        System.out.println("Final Balance 2: " + account2.getBalance().getAmount());
    }
}

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
