public class MoneyTransferProgram {

    private static final Object tieLock = new Object();

    public static void main(String[] args) {
        Account account1 = new BankAccount("Account1", new DollarAmountImpl(1000));
        Account account2 = new BankAccount("Account2", new DollarAmountImpl(500));
        Account account3 = new BankAccount("Account3", new DollarAmountImpl(750));

        ExecutorService executor = Executors.newFixedThreadPool(2);

        executor.submit(() -> {
            for (int i = 0; i < 5; i++) {
                try {
                    transferMoney(account1, account2, new DollarAmountImpl(100));
                    System.out.println("Transfer 1->2 completed");
                } catch (InsufficientFundsException e) {
                    System.out.println("Transfer 1->2 failed: " + e.getMessage());
                }
            }
        });

        executor.submit(() -> {
            for (int i = 0; i < 5; i++) {
                try {
                    transferMoney(account2, account3, new DollarAmountImpl(50));
                    System.out.println("Transfer 2->3 completed");
                } catch (InsufficientFundsException e) {
                    System.out.println("Transfer 2->3 failed: " + e.getMessage());
                }
            }
        });

        executor.shutdown();
        try {
            executor.awaitTermination(10, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println("Final balances:");
        System.out.println("Account1: " + account1.getBalance().getAmount());
        System.out.println("Account2: " + account2.getBalance().getAmount());
        System.out.println("Account3: " + account3.getBalance().getAmount());
    }

    public static void transferMoney(Account fromAccount, Account toAccount, DollarAmount amount) 
            throws InsufficientFundsException {
        int fromHash = System.identityHashCode(fromAccount);
        int toHash = System.identityHashCode(toAccount);

        if (fromHash < toHash) {
            synchronized (fromAccount) {
                synchronized (toAccount) {
                    new TransferHelper().doTransfer(fromAccount, toAccount, amount);
                }
            }
        } else if (fromHash > toHash) {
            synchronized (toAccount) {
                synchronized (fromAccount) {
                    new TransferHelper().doTransfer(fromAccount, toAccount, amount);
                }
            }
        } else {
            synchronized (tieLock) {
                synchronized (fromAccount) {
                    synchronized (toAccount) {
                        new TransferHelper().doTransfer(fromAccount, toAccount, amount);
                    }
                }
            }
        }
    }
}

