class TransferHelper {
    public void doTransfer(Account fromAccount, Account toAccount, DollarAmount amount) 
            throws InsufficientFundsException {
        if (fromAccount.getBalance().isLessThan(amount)) {
            throw new InsufficientFundsException("Insufficient funds in source account");
        }
        fromAccount.debit(amount);
        toAccount.credit(amount);
    }
}

class BankAccount implements Account {
    private final String name;
    private DollarAmount balance;

    public BankAccount(String name, DollarAmount initialBalance) {
        this.name = name;
        this.balance = initialBalance;
    }

    public DollarAmount getBalance() {
        return balance;
    }

    public void debit(DollarAmount amount) throws InsufficientFundsException {
        if (balance.isLessThan(amount)) {
            throw new InsufficientFundsException("Cannot debit more than balance");
        }
        balance = balance.subtract(amount);
    }

    public void credit(DollarAmount amount) {
        balance = balance.add(amount);
    }
}

class DollarAmountImpl implements DollarAmount {
    private final long amount;

    public DollarAmountImpl(long amount) {
        this.amount = amount;
    }

    public long getAmount() {
        return amount;
    }

    public DollarAmount add(DollarAmount other) {
        return new DollarAmountImpl(amount + other.getAmount());
