class CasCounter {
    private final SimulatedCAS cas;

    public CasCounter() {
        this.cas = new SimulatedCAS();
    }

    public int getValue() {
        return cas.getValue();
    }

    public void increment() {
        while (true) {
            int current = cas.getValue();
            int next = current + 1;
            int witness = cas.compareAndSwap(current, next);
            if (witness == current) {
                break;
            }
        }
    }
}

class SimulatedCAS {
    private volatile int value;

    public SimulatedCAS() {
        this.value = 0;
    }

    public synchronized int compareAndSwap(int expected, int newValue) {
        int oldValue = value;
        if (oldValue == expected) {
            value = newValue;
        }
        return oldValue;
    }

    public int getValue() {
        return value;
    }
}

