import java.util.concurrent.atomic.AtomicReference;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class TreiberStack<T> {

    private final AtomicReference<Node<T>> top = new AtomicReference<>();

    static class Node<T> {
        final T item;
        final Node<T> next;

        Node(T item, Node<T> next) {
            this.item = item;
            this.next = next;
        }
    }

    public void push(T item) {
        Node<T> newHead = new Node<>(item, null);
        while (true) {
            Node<T> currentHead = top.get();
            newHead = new Node<>(item, currentHead);
            if (top.compareAndSet(currentHead, newHead)) {
                break;
            }
        }
    }

    public T pop() {
        while (true) {
            Node<T> currentHead = top.get();
            if (currentHead == null) {
                return null;
            }
            Node<T> newHead = currentHead.next;
            if (top.compareAndSet(currentHead, newHead)) {
                return currentHead.item;
            }
        }
    }

    public static void main(String[] args) {
        TreiberStack<Integer> stack = new TreiberStack<>();
        ExecutorService executor = Executors.newFixedThreadPool(3);

        Runnable task = () -> {
            String threadName = Thread.currentThread().getName();
            for (int i = 1; i <= 5; i++) {
                stack.push(i);
                System.out.println(threadName + " pushed: " + i);
            }
            for (int i = 1; i <= 5; i++) {
                Integer value = stack.pop();
                System.out.println(threadName + " popped: " + value);
            }
        };

        for (int i = 0; i < 3; i++) {
            executor.submit(task);
        }

        executor.shutdown();
        try {
            executor.awaitTermination(10, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println("All threads completed");
    }
}

