import java.util.*;
import java.util.concurrent.*;

public class DelegatingVehicleTracker {
    private final ConcurrentHashMap<String, Point> locations;
    private final Map<String, Point> unmodifiableMap;

    public DelegatingVehicleTracker(Map<String, Point> points) {
        locations = new ConcurrentHashMap<>(points);
        unmodifiableMap = Collections.unmodifiableMap(locations);
    }

    public Map<String, Point> getLocations() {
        return unmodifiableMap;
    }

    public Map<String, Point> getLocationsAsStatic() {
        return Collections.unmodifiableMap(
            new HashMap<>(locations));
    }

    public Point getLocation(String id) {
        return locations.get(id);
    }

    public boolean setLocation(String id, int x, int y) {
        if (locations.containsKey(id)) {
            locations.put(id, new Point(x, y));
            return true;
        }
        return false;
    }

    public static void main(String[] args) {
        // Initialize tracker with some vehicles
        Map<String, Point> initialLocations = new HashMap<>();
        initialLocations.put("vehicle1", new Point(0, 0));
        initialLocations.put("vehicle2", new Point(10, 10));
        initialLocations.put("vehicle3", new Point(20, 20));

        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initialLocations);

        System.out.println("Initial locations:");
        printLocations(tracker.getLocations());

        // Create a fixed thread pool with 2 threads (plus main thread = 3 total)
        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Task 1: Continuously update vehicle1's location
        Runnable updateTask = () -> {
            String threadName = Thread.currentThread().getName();
            for (int i = 0; i < 5; i++) {
                int newX = (int)(Math.random() * 100);
                int newY = (int)(Math.random() * 100);
                boolean updated = tracker.setLocation("vehicle1", newX, newY);
                System.out.println(threadName + " - Updated vehicle1 to (" + 
                                 newX + ", " + newY + "): " + updated);

                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        };

        // Task 2: Read and display locations
        Runnable readTask = () -> {
            String threadName = Thread.currentThread().getName();
            for (int i = 0; i < 5; i++) {
                Point location = tracker.getLocation("vehicle1");
                System.out.println(threadName + " - Read vehicle1 location: " + location);

                // Test static snapshot vs live view
                if (i == 2) {
                    System.out.println(threadName + " - Getting snapshots:");
                    Map<String, Point> liveView = tracker.getLocations();
                    Map<String, Point> staticSnapshot = tracker.getLocationsAsStatic();

                    System.out.println("  Live view size: " + liveView.size());
                    System.out.println("  Static snapshot size: " + staticSnapshot.size());
                }

                try {
                    Thread.sleep(150);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        };

        // Submit tasks to executor
        Future<?> updateFuture = executor.submit(updateTask);
        Future<?> readFuture = executor.submit(readTask);

        // Main thread also performs some operations
        System.out.println("\nMain thread operations:");
        for (int i = 0; i < 3; i++) {
            boolean updated = tracker.setLocation("vehicle2", i * 5, i * 5);
            System.out.println("Main - Updated vehicle2 to (" + 
                             (i * 5) + ", " + (i * 5) + "): " + updated);

            // Try to update non-existent vehicle
            boolean failedUpdate = tracker.setLocation("vehicle99", 50, 50);
            System.out.println("Main - Attempted to update non-existent vehicle99: " + failedUpdate);

            try {
                Thread.sleep(200);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }

        // Wait for tasks to complete
        try {
            updateFuture.get(3, TimeUnit.SECONDS);
            readFuture.get(3, TimeUnit.SECONDS);
        } catch (InterruptedException | ExecutionException | TimeoutException e) {
            System.err.println("Error waiting for tasks: " + e.getMessage());
        }

        // Shutdown executor
        executor.shutdown();
        try {
            if (!executor.awaitTermination(1, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }

        System.out.println("\nFinal locations:");
        printLocations(tracker.getLocations());

        // Demonstrate difference between live view and static snapshot
        System.out.println("\nDemonstrating live view vs static snapshot:");
        Map<String, Point> liveView = tracker.getLocations();
        Map<String, Point> staticSnapshot = tracker.getLocationsAsStatic();

        System.out.println("Before update:");
        System.out.println("  vehicle3 in live view: " + liveView.get("vehicle3"));
        System.out.println("  vehicle3 in static snapshot: " + staticSnapshot.get("vehicle3"));

        tracker.setLocation("vehicle3", 99, 99);

        System.out.println("After update:");
        System.out.println("  vehicle3 in live view: " + liveView.get("vehicle3"));
        System.out.println("  vehicle3 in static snapshot: " + staticSnapshot.get("vehicle3"));

        // Test immutability
        System.out.println("\nTesting immutability:");
        try {
            liveView.put("newVehicle", new Point(0, 0));
            System.out.println("ERROR: Live view should be unmodifiable!");
        } catch (UnsupportedOperationException e) {
            System.out.println("Live view is correctly unmodifiable");
        }

        try {
            staticSnapshot.put("newVehicle", new Point(0, 0));
            System.out.println("ERROR: Static snapshot should be unmodifiable!");
        } catch (UnsupportedOperationException e) {
            System.out.println("Static snapshot is correctly unmodifiable");
        }
    }

    private static void printLocations(Map<String, Point> locations) {
        for (Map.Entry<String, Point> entry : locations.entrySet()) {
            System.out.println("  " + entry.getKey() + ": " + entry.getValue());
        }
    }
}

