import java.util.*;
import java.util.concurrent.*;

public class DelegatingVehicleTracker {
    private final ConcurrentMap<String, Point> locations;
    private final Map<String, Point> unmodifiableMap;

    public DelegatingVehicleTracker(Map<String, Point> points) {
        this.locations = new ConcurrentHashMap<>(points);
        this.unmodifiableMap = Collections.unmodifiableMap(this.locations);
    }

    // Get location of a specific vehicle
    public Point getLocation(String id) {
        Point loc = locations.get(id);
        return loc == null ? null : new Point(loc);
    }

    // Set location of a vehicle (only if vehicle ID exists)
    public boolean setLocation(String id, int x, int y) {
        if (locations.containsKey(id)) {
            locations.put(id, new Point(x, y));
            return true;
        }
        return false;
    }

    // Returns a live unmodifiable view backed by the original data
    public Map<String, Point> getLocationsLive() {
        return unmodifiableMap;
    }

    // Returns a static snapshot of the current state as an unmodifiable map
    public Map<String, Point> getLocationsSnapshot() {
        Map<String, Point> snapshot = new HashMap<>();
        for (Map.Entry<String, Point> entry : locations.entrySet()) {
            snapshot.put(entry.getKey(), new Point(entry.getValue()));
        }
        return Collections.unmodifiableMap(snapshot);
    }

    public static void main(String[] args) {
        // Initialize with some vehicles
        Map<String, Point> initialLocations = new HashMap<>();
        initialLocations.put("vehicle1", new Point(10, 20));
        initialLocations.put("vehicle2", new Point(30, 40));
        initialLocations.put("vehicle3", new Point(50, 60));

        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initialLocations);

        // Create a fixed thread pool with 2 threads (plus main thread = 3 total)
        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Thread 1: Continuously update vehicle locations
        executor.submit(() -> {
            String threadName = Thread.currentThread().getName();
            Random random = new Random();
            for (int i = 0; i < 10; i++) {
                String vehicleId = "vehicle" + (random.nextInt(3) + 1);
                int newX = random.nextInt(100);
                int newY = random.nextInt(100);

                boolean updated = tracker.setLocation(vehicleId, newX, newY);
                if (updated) {
                    System.out.println("[" + threadName + "] Updated " + vehicleId + 
                                     " to position (" + newX + ", " + newY + ")");
                }

                // Try to update a non-existent vehicle (should fail)
                boolean failedUpdate = tracker.setLocation("vehicle99", 0, 0);
                if (!failedUpdate && i == 0) {
                    System.out.println("[" + threadName + "] Failed to update non-existent vehicle99 (expected)");
                }

                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });

        // Thread 2: Continuously read vehicle locations
        executor.submit(() -> {
            String threadName = Thread.currentThread().getName();
            for (int i = 0; i < 10; i++) {
                // Get specific vehicle location
                Point vehicle1Loc = tracker.getLocation("vehicle1");
                System.out.println("[" + threadName + "] Vehicle1 location: " + vehicle1Loc);

                // Get live view (changes will be reflected)
                Map<String, Point> liveView = tracker.getLocationsLive();
                System.out.println("[" + threadName + "] Live view size: " + liveView.size());

                // Get snapshot (frozen state)
                Map<String, Point> snapshot = tracker.getLocationsSnapshot();
                System.out.println("[" + threadName + "] Snapshot: " + snapshot);

                try {
                    Thread.sleep(150);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        });

        // Main thread: Demonstrate the difference between live view and snapshot
        try {
            Thread.sleep(500);

            System.out.println("\n[Main Thread] Demonstrating live view vs snapshot:");
            Map<String, Point> liveView = tracker.getLocationsLive();
            Map<String, Point> snapshot = tracker.getLocationsSnapshot();

            System.out.println("[Main Thread] Initial live view: " + liveView);
            System.out.println("[Main Thread] Initial snapshot: " + snapshot);

            // Update a location
            tracker.setLocation("vehicle1", 999, 999);

            System.out.println("[Main Thread] After update:");
            System.out.println("[Main Thread] Live view (should show update): " + liveView);
            System.out.println("[Main Thread] Snapshot (should NOT show update): " + snapshot);

            // Try to modify the unmodifiable maps (will throw exception)
            try {
                liveView.put("newVehicle", new Point(0, 0));
            } catch (UnsupportedOperationException e) {
                System.out.println("[Main Thread] Cannot modify live view (expected)");
            }

            try {
                snapshot.put("newVehicle", new Point(0, 0));
            } catch (UnsupportedOperationException e) {
                System.out.println("[Main Thread] Cannot modify snapshot (expected)");
            }

        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        // Shutdown executor
        executor.shutdown();
        try {
            if (!executor.awaitTermination(2, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }

        System.out.println("\n[Main Thread] Final state of all vehicles:");
        Map<String, Point> finalSnapshot = tracker.getLocationsSnapshot();
        for (Map.Entry<String, Point> entry : finalSnapshot.entrySet()) {
            System.out.println("  " + entry.getKey() + ": " + entry.getValue());
        }
    }
}

