        initialLocations.put("vehicle1", new Point(0, 0));
        initialLocations.put("vehicle2", new Point(10, 20));
        initialLocations.put("vehicle3", new Point(30, 40));

        DelegatingVehicleTracker tracker = new DelegatingVehicleTracker(initialLocations);

        // Create executor service with 2 threads (plus main thread = 3 total)
        ExecutorService executor = Executors.newFixedThreadPool(2);

        // Create concurrent tasks
        Runnable updater1 = new VehicleUpdater(tracker, "vehicle1", 1);
        Runnable updater2 = new VehicleUpdater(tracker, "vehicle2", 2);

        // Submit tasks
        Future<?> future1 = executor.submit(updater1);
        Future<?> future2 = executor.submit(updater2);

        // Main thread also performs some operations
        System.out.println("Initial locations (live view): " + tracker.getLocations());
        System.out.println("Initial locations (static snapshot): " + tracker.getLocationsAsStatic());

        // Main thread updates vehicle3
        for (int i = 0; i < 5; i++) {
            tracker.setLocation("vehicle3", 100 + i * 10, 200 + i * 10);
            System.out.println("Main thread updated vehicle3 to: " + tracker.getLocation("vehicle3"));
            try {
                Thread.sleep(100);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

        // Try to update non-existent vehicle
        boolean success = tracker.setLocation("vehicle4", 500, 600);
        System.out.println("Attempt to update non-existent vehicle4: " + (success ? "Success" : "Failed"));

        // Wait for tasks to complete
        try {
            future1.get();
            future2.get();
        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        }

        // Shutdown executor
        executor.shutdown();
        try {
            if (!executor.awaitTermination(1, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
        }

        // Display final state
        System.out.println("\nFinal locations:");
        Map<String, Point> finalLocations = tracker.getLocations();
        for (Map.Entry<String, Point> entry : finalLocations.entrySet()) {
            System.out.println(entry.getKey() + ": " + entry.getValue());
        }

        // Demonstrate difference between live view and static snapshot
        System.out.println("\nDemonstrating live view vs static snapshot:");
        Map<String, Point> liveView = tracker.getLocations();
        Map<String, Point> staticSnapshot = tracker.getLocationsAsStatic();

        System.out.println("Before update - Live view vehicle1: " + liveView.get("vehicle1"));
        System.out.println("Before update - Static snapshot vehicle1: " + staticSnapshot.get("vehicle1"));

        tracker.setLocation("vehicle1", 999, 999);

        System.out.println("After update - Live view vehicle1: " + liveView.get("vehicle1"));
        System.out.println("After update - Static snapshot vehicle1: " + staticSnapshot.get("vehicle1"));
    }
}

