        this.y = y;
    }

    public int getX() {
        return x;
    }

    public int getY() {
        return y;
    }

    @Override
    public String toString() {
        return "Point[x=" + x + ", y=" + y + "]";
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Point point = (Point) o;
        return x == point.x && y == point.y;
    }

    @Override
    public int hashCode() {
        return Objects.hash(x, y);
    }
}

class VehicleUpdater implements Runnable {
    private final DelegatingVehicleTracker tracker;
    private final String vehicleId;
    private final int threadId;

    public VehicleUpdater(DelegatingVehicleTracker tracker, String vehicleId, int threadId) {
        this.tracker = tracker;
        this.vehicleId = vehicleId;
        this.threadId = threadId;
    }

    @Override
    public void run() {
        for (int i = 0; i < 10; i++) {
            int newX = threadId * 100 + i;
            int newY = threadId * 200 + i;
            boolean updated = tracker.setLocation(vehicleId, newX, newY);

            if (updated) {
                System.out.println("Thread " + threadId + " updated " + vehicleId + 
                                 " to: " + tracker.getLocation(vehicleId));
            } else {
                System.out.println("Thread " + threadId + " failed to update " + vehicleId);
            }

            try {
                Thread.sleep(50);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return;
            }
        }
        System.out.println("Thread " + threadId + " completed updates for " + vehicleId);
    }
}

