import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class SimulatedCAS {
    private int value;

    public SimulatedCAS(int initialValue) {
        this.value = initialValue;
    }

    public synchronized int get() {
        return value;
    }

    public synchronized int compareAndSwap(int expectedValue, int newValue) {
        int oldValue = value;
        if (oldValue == expectedValue) {
            value = newValue;
        }
        return oldValue;
    }

    public synchronized boolean compareAndSet(int expectedValue, int newValue) {
        return compareAndSwap(expectedValue, newValue) == expectedValue;
    }

    public static void main(String[] args) {
        SimulatedCAS cas = new SimulatedCAS(0);
        ExecutorService executor = Executors.newFixedThreadPool(1);

        Runnable task1 = () -> {
            for (int i = 0; i < 5; i++) {
                int current = cas.get();
                boolean success = cas.compareAndSet(current, current + 1);
                System.out.println("Thread 1: " + current + " -> " + (current + 1) + ", success: " + success);
                try {
                    Thread.sleep(10);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        Runnable task2 = () -> {
            for (int i = 0; i < 5; i++) {
                int current = cas.get();
                boolean success = cas.compareAndSet(current, current + 10);
                System.out.println("Thread 2: " + current + " -> " + (current + 10) + ", success: " + success);
                try {
                    Thread.sleep(15);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        };

        executor.submit(task1);

        for (int i = 0; i < 5; i++) {
            int current = cas.get();
            int oldValue = cas.compareAndSwap(current, current + 100);
            System.out.println("Main thread: old value: " + oldValue + ", new value: " + cas.get());
            try {
                Thread.sleep(20);
