enum Species {
    DOG, CAT, BIRD, ELEPHANT, LION
}

enum Gender {
    MALE, FEMALE
}

class Animal {
    private final Species species;
    private final Gender gender;

    public Animal(Species species, Gender gender) {
        this.species = species;
        this.gender = gender;
    }

    public Species getSpecies() {
        return species;
    }

    public Gender getGender() {
        return gender;
    }

    @Override
    public String toString() {
        return species + " " + gender;
    }
}

class AnimalPair {
    private final Animal first;
    private final Animal second;

    public AnimalPair(Animal first, Animal second) {
        this.first = first;
        this.second = second;
    }

    public Animal getFirst() {
        return first;
    }

    public Animal getSecond() {
        return second;
    }

    @Override
    public String toString() {
        return "(" + first + ", " + second + ")";
    }
}

class Ark {
    private final List<AnimalPair> pairs = Collections.synchronizedList(new ArrayList<>());

    public int loadTheArk(Collection<Animal> candidates) {
        ExecutorService executor = Executors.newFixedThreadPool(2);
        List<Animal> animalList = new ArrayList<>(candidates);

        Comparator<Animal> animalComparator = Comparator
            .comparing(Animal::getSpecies)
            .thenComparing(Animal::getGender);

        Future<List<Animal>> sortingTask = executor.submit(() -> {
            List<Animal> sorted = new ArrayList<>(animalList);
            Collections.sort(sorted, animalComparator);
            return sorted;
        });

        try {
            List<Animal> sortedAnimals = sortingTask.get();

            int midPoint = sortedAnimals.size() / 2;
            List<Animal> firstHalf = sortedAnimals.subList(0, midPoint);
            List<Animal> secondHalf = sortedAnimals.subList(midPoint, sortedAnimals.size());

            Future<List<AnimalPair>> firstHalfPairing = executor.submit(() -> {
                return pairAnimals(firstHalf);
            });

            Future<List<AnimalPair>> secondHalfPairing = executor.submit(() -> {
                return pairAnimals(secondHalf);
            });

            List<AnimalPair> pairs1 = firstHalfPairing.get();
            List<AnimalPair> pairs2 = secondHalfPairing.get();

            pairs.addAll(pairs1);
            pairs.addAll(pairs2);

            if (midPoint > 0 && sortedAnimals.size() > midPoint) {
                Animal lastOfFirst = sortedAnimals.get(midPoint - 1);
                Animal firstOfSecond = sortedAnimals.get(midPoint);
                if (canPair(lastOfFirst, firstOfSecond)) {
                    pairs.add(new AnimalPair(lastOfFirst, firstOfSecond));
                }
            }

        } catch (InterruptedException | ExecutionException e) {
            e.printStackTrace();
        } finally {
            executor.shutdown();
        }

        return pairs.size();
    }

    private List<AnimalPair> pairAnimals(List<Animal> animals) {
        List<AnimalPair> localPairs = new ArrayList<>();
        Map<Species, List<Animal>> speciesGroups = new HashMap<>();

        for (Animal animal : animals) {
            speciesGroups.computeIfAbsent(animal.getSpecies(), k -> new ArrayList<>()).add(animal);
        }

        for (Map.Entry<Species, List<Animal>> entry : speciesGroups.entrySet()) {
            List<Animal> speciesAnimals = entry.getValue();
            List<Animal> males = new ArrayList<>();
            List<Animal> females = new ArrayList<>();

            for (Animal animal : speciesAnimals) {
                if (animal.getGender() == Gender.MALE) {
                    males.add(animal);
                } else {
                    females.add(animal);
                }
            }

            int pairCount = Math.min(males.size(), females.size());
            for (int i = 0; i < pairCount; i++) {
                localPairs.add(new AnimalPair(males.get(i), females.get(i)));
            }
        }

        return localPairs;
    }

    private boolean canPair(Animal a1, Animal a2) {
        return a1.getSpecies() == a2.getSpecies() && 
               a1.getGender() != a2.getGender();
    }

    public List<AnimalPair> getPairs() {
        return new ArrayList<>(pairs);
    }
}

