import java.util.concurrent.*;
import java.util.stream.*;

public class ArkLoader {
    public static void main(String[] args) throws Exception {
        List<Animal> animals = Arrays.asList(
            new Animal(Species.DOG, Gender.MALE),
            new Animal(Species.DOG, Gender.FEMALE),
            new Animal(Species.CAT, Gender.MALE),
            new Animal(Species.CAT, Gender.FEMALE),
            new Animal(Species.BIRD, Gender.MALE),
            new Animal(Species.BIRD, Gender.FEMALE),
            new Animal(Species.DOG, Gender.MALE),
            new Animal(Species.CAT, Gender.FEMALE)
        );

        ExecutorService executor = Executors.newFixedThreadPool(2);
        Future<Integer> future = executor.submit(() -> loadTheArk(animals));

        int pairs = future.get();
        System.out.println("Number of pairs loaded: " + pairs);

        executor.shutdown();
        executor.awaitTermination(10, TimeUnit.SECONDS);
    }

    public static int loadTheArk(Collection<Animal> candidates) {
        List<Animal> sortedAnimals = new ArrayList<>(candidates);
        Collections.sort(sortedAnimals, new AnimalComparator());

        Ark ark = new Ark();
        int pairCount = 0;

        ExecutorService executor = Executors.newFixedThreadPool(2);
        List<Future<AnimalPair>> futures = new ArrayList<>();

        for (int i = 0; i < sortedAnimals.size() - 1; i++) {
            final int index = i;
            final List<Animal> localList = new ArrayList<>(sortedAnimals);

            Future<AnimalPair> future = executor.submit(() -> {
                Animal first = localList.get(index);
                Animal second = localList.get(index + 1);

                if (first.getSpecies() == second.getSpecies() && 
                    first.getGender() != second.getGender()) {
                    return new AnimalPair(first, second);
                }
                return null;
            });

            futures.add(future);
        }

        for (Future<AnimalPair> future : futures) {
            try {
                AnimalPair pair = future.get();
                if (pair != null) {
                    synchronized (ark) {
                        ark.addPair(pair);
                        pairCount++;
                    }
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        executor.shutdown();
        try {
            executor.awaitTermination(10, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        return pairCount;
    }
}

