import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class LazyInitialization {

    private static Resource instance;

    public static synchronized Resource getInstance() {
        if (instance == null) {
            instance = new Resource();
        }
        return instance;
    }

    static class Resource {
        private final long creationTime;
        private final long threadId;

        public Resource() {
            this.creationTime = System.currentTimeMillis();
            this.threadId = Thread.currentThread().getId();
            System.out.println("Resource created by thread " + threadId + " at " + creationTime);
        }

        public void doWork() {
            System.out.println("Working with resource created by thread " + threadId + 
                             " (called from thread " + Thread.currentThread().getId() + ")");
        }
    }

    public static void main(String[] args) {
        ExecutorService executor = Executors.newFixedThreadPool(3);

        for (int i = 0; i < 10; i++) {
            final int taskId = i;
            executor.submit(() -> {
                System.out.println("Task " + taskId + " requesting resource from thread " + 
                                 Thread.currentThread().getId());
                Resource resource = getInstance();
                resource.doWork();
            });
        }

        executor.shutdown();
        try {
            executor.awaitTermination(5, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

