public class ConcurrentPerformanceTester {

    public static void main(String[] args) {
        ConcurrentPerformanceTester tester = new ConcurrentPerformanceTester();

        Runnable task = () -> {
            long sum = 0;
            for (int i = 0; i < 1000000; i++) {
                sum += i;
            }
        };

        try {
            long time1 = tester.timeTasks(1, task);
            System.out.println("Single thread execution time: " + time1 + " ns");

            long time2 = tester.timeTasks(2, task);
            System.out.println("Two threads execution time: " + time2 + " ns");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.err.println("Test interrupted");
        }
    }

    public long timeTasks(int nThreads, Runnable task) throws InterruptedException {
        if (nThreads > 2) {
            nThreads = 2;
        }

        CountDownLatch startGate = new CountDownLatch(1);
        CountDownLatch endGate = new CountDownLatch(nThreads);

        for (int i = 0; i < nThreads; i++) {
