import java.util.concurrent.Callable;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.FutureTask;
import java.util.concurrent.TimeUnit;

interface ProductInfo {
    String getName();
    double getPrice();
}

class DataLoadException extends Exception {
    public DataLoadException(String message) {
        super(message);
    }

    public DataLoadException(String message, Throwable cause) {
        super(message, cause);
    }
}

class ProductInfoImpl implements ProductInfo {
    private final String name;
    private final double price;

    public ProductInfoImpl(String name, double price) {
        this.name = name;
        this.price = price;
    }

    public String getName() {
        return name;
    }

    public double getPrice() {
        return price;
    }
}

class Preloader {
    private final FutureTask<ProductInfo> future;
    private final Thread thread;

    public Preloader() {
        this.future = new FutureTask<>(new Callable<ProductInfo>() {
            @Override
            public ProductInfo call() throws DataLoadException {
                return loadProductInfo();
            }
        });
        this.thread = new Thread(future);
    }

    private ProductInfo loadProductInfo() throws DataLoadException {
        try {
            TimeUnit.SECONDS.sleep(2);
            if (Math.random() > 0.7) {
                throw new DataLoadException("Failed to load product data");
            }
            return new ProductInfoImpl("Sample Product", 99.99);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new DataLoadException("Loading interrupted", e);
        }
    }

    public void start() {
        thread.start();
    }

    public ProductInfo get() throws DataLoadException {
        try {
            return future.get();
        } catch (ExecutionException e) {
            Throwable cause = e.getCause();
            if (cause instanceof DataLoadException) {
                throw (DataLoadException) cause;
            } else {
                throw launderThrowable(cause);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new DataLoadException("Interrupted while waiting for result", e);
        }
    }

    private static RuntimeException launderThrowable(Throwable t) {
        if (t instanceof RuntimeException) {
            return (RuntimeException) t;
        } else if (t instanceof Error) {
            throw (Error) t;
        } else {
            throw new IllegalStateException("Unexpected exception", t);
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Preloader preloader = new Preloader();
        System.out.println("Starting preloader...");
        preloader.start();

        System.out.println("Doing other work...");
        try {
            TimeUnit.SECONDS.sleep(1);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println("Retrieving preloaded data...");
        try {
            ProductInfo product = preloader.get();
            System.out.println("Product loaded: " + product.getName() + " - $" + product.getPrice());
        } catch (DataLoadException e) {
            System.err.println("Failed to load product: " + e.getMessage());
        }
    }
}

