import java.util.*;
import java.util.concurrent.*;

public class PrimeGenerator {

    private volatile boolean cancelled = false;
    private final List<Integer> primes = Collections.synchronizedList(new ArrayList<>());

    public void generatePrimes() {
        int num = 2;
        while (!cancelled) {
            if (isPrime(num)) {
                primes.add(num);
            }
            num++;
        }
    }

    private boolean isPrime(int n) {
        if (n <= 1) return false;
        if (n <= 3) return true;
        if (n % 2 == 0 || n % 3 == 0) return false;
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }

    public void cancel() {
        cancelled = true;
    }

    public List<Integer> getPrimes() {
        return new ArrayList<>(primes);
    }

    public static void main(String[] args) {
        PrimeGenerator generator = new PrimeGenerator();
        ExecutorService executor = Executors.newSingleThreadExecutor();

        Future<?> future = executor.submit(() -> generator.generatePrimes());

        try {
            Thread.sleep(1000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        generator.cancel();

        try {
            future.get(100, TimeUnit.MILLISECONDS);
        } catch (InterruptedException | ExecutionException | TimeoutException e) {
            future.cancel(true);
        }

        executor.shutdown();
        try {
            if (!executor.awaitTermination(100, TimeUnit.MILLISECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }

        List<Integer> foundPrimes = generator.getPrimes();
        System.out.println("Found " + foundPrimes.size() + " prime numbers");
        System.out.println("Primes: " + foundPrimes);
    }
}

