import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class PrimeGenerator {
    private volatile boolean cancelled = false;
    private final List<Integer> primes = Collections.synchronizedList(new ArrayList<>());

    public void generatePrimes() {
        int number = 2;
        while (!cancelled) {
            if (isPrime(number)) {
                primes.add(number);
            }
            number++;
        }
    }

    private boolean isPrime(int n) {
        if (n <= 1) return false;
        if (n <= 3) return true;
        if (n % 2 == 0 || n % 3 == 0) return false;
        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) return false;
        }
        return true;
    }

    public void cancel() {
        cancelled = true;
    }

    public List<Integer> getPrimes() {
        return new ArrayList<>(primes);
    }

    public static void main(String[] args) {
        PrimeGenerator generator = new PrimeGenerator();
        ExecutorService executor = Executors.newSingleThreadExecutor();

        executor.submit(() -> generator.generatePrimes());

        try {
            Thread.sleep(1000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        generator.cancel();
        executor.shutdown();

        try {
            if (!executor.awaitTermination(1, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }

        List<Integer> foundPrimes = generator.getPrimes();
        System.out.println("Found " + foundPrimes.size() + " prime numbers");
        System.out.println("First 10 primes: " + foundPrimes.subList(0, Math.min(10, foundPrimes.size())));
        System.out.println("Last prime found: " + (foundPrimes.isEmpty() ? "None" : foundPrimes.get(foundPrimes.size() - 1)));
    }
}

