import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

public class PrimeProducerConsumer {
    public static void main(String[] args) {
        int numberOfPrimes = 10;
        BlockingQueue<BigInteger> queue = new LinkedBlockingQueue<>();
        AtomicBoolean producerFinished = new AtomicBoolean(false);
        AtomicInteger primesConsumed = new AtomicInteger(0);

        PrimeProducer producer = new PrimeProducer(queue, numberOfPrimes, producerFinished);

        Thread consumer = new Thread(() -> {
            try {
                while (primesConsumed.get() < numberOfPrimes) {
                    BigInteger prime = queue.poll(100, TimeUnit.MILLISECONDS);
                    if (prime != null) {
                        System.out.println("Consumed prime: " + prime);
                        primesConsumed.incrementAndGet();
                    } else if (producerFinished.get()) {
                        break;
                    }
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        });

        producer.start();
        consumer.start();

        try {
            consumer.join();
            producer.interrupt();
            producer.join();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

class PrimeProducer extends Thread {
    private final BlockingQueue<BigInteger> queue;
    private final int numberOfPrimes;
    private final AtomicBoolean finished;

    public PrimeProducer(BlockingQueue<BigInteger> queue, int numberOfPrimes, AtomicBoolean finished) {
        this.queue = queue;
        this.numberOfPrimes = numberOfPrimes;
        this.finished = finished;
    }

    @Override
    public void run() {
        try {
            BigInteger prime = BigInteger.valueOf(2);
            for (int i = 0; i < numberOfPrimes && !Thread.currentThread().isInterrupted(); i++) {
                prime = prime.nextProbablePrime();
                queue.put(prime);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        } finally {
            finished.set(true);
        }
    }
}

