import java.util.*;
import java.util.concurrent.*;

interface Element {
    String getId();
    void process();
}

interface Node {
    String compute();
    List<Node> getChildren();
}

class SimpleElement implements Element {
    private final String id;

    public SimpleElement(String id) {
        this.id = id;
    }

    @Override
    public String getId() {
        return id;
    }

    @Override
    public void process() {
        try {
            Thread.sleep(100);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

class TreeNode implements Node {
    private final String value;
    private final List<Node> children;

    public TreeNode(String value, List<Node> children) {
        this.value = value;
        this.children = children;
    }

    @Override
    public String compute() {
        try {
            Thread.sleep(50);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return value;
    }

    @Override
    public List<Node> getChildren() {
        return children;
    }
}

class Processor {
    private final ExecutorService executor;

    public Processor() {
        this.executor = Executors.newFixedThreadPool(1);
    }

    public void processSequential(List<Element> elements) {
        for (Element element : elements) {
            element.process();
        }
    }

    public void processParallel(List<Element> elements) {
        List<Future<?>> futures = new ArrayList<>();
        for (Element element : elements) {
            futures.add(executor.submit(() -> element.process()));
        }
        for (Future<?> future : futures) {
            try {
                future.get();
            } catch (InterruptedException | ExecutionException e) {
                Thread.currentThread().interrupt();
            }
        }
    }

    public List<String> processTreeSequential(Node root) {
        List<String> results = new ArrayList<>();
        processNodeSequential(root, results);
        return results;
    }

    private void processNodeSequential(Node node, List<String> results) {
        if (node == null) return;
        results.add(node.compute());
        for (Node child : node.getChildren()) {
            processNodeSequential(child, results);
        }
    }

    public List<String> processTreeParallel(Node root) {
        ConcurrentLinkedQueue<String> results = new ConcurrentLinkedQueue<>();
        CountDownLatch latch = processNodeParallel(root, results);
        try {
            latch.await();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return new ArrayList<>(results);
    }

    private CountDownLatch processNodeParallel(Node node, ConcurrentLinkedQueue<String> results) {
        if (node == null) return new CountDownLatch(0);

        List<Node> children = node.getChildren();
        CountDownLatch latch = new CountDownLatch(1 + children.size());

        executor.submit(() -> {
            results.add(node.compute());
            latch.countDown();
        });

        for (Node child : children) {
            executor.submit(() -> {
                processNodeParallelHelper(child, results);
                latch.countDown();
            });
        }

        return latch;
    }

    private void processNodeParallelHelper(Node node, ConcurrentLinkedQueue<String> results) {
        if (node == null) return;
        results.add(node.compute());
        for (Node child : node.getChildren()) {
            processNodeParallelHelper(child, results);
        }
    }

    public void shutdown() {
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }
}

public class ConcurrentProgram {
    public static void main(String[] args) {
        Processor processor = new Processor();

        List<Element> elements = Arrays.asList(
            new SimpleElement("1"),
            new SimpleElement("2"),
            new SimpleElement("3")
        );

        long start = System.currentTimeMillis();
        processor.processSequential(elements);
        System.out.println("Sequential processing time: " + (System.currentTimeMillis() - start) + "ms");

        start = System.currentTimeMillis();
        processor.processParallel(elements);
        System.out.println("Parallel processing time: " + (System.currentTimeMillis() - start) + "ms");

        Node root = new TreeNode("root", Arrays.asList(
            new TreeNode("child1", Arrays.asList(
                new TreeNode("grandchild1", Collections.emptyList()),
                new TreeNode("grandchild2", Collections.emptyList())
            )),
            new TreeNode("child2", Arrays.asList(
                new TreeNode("grandchild3", Collections.emptyList())
            ))
        ));

        start = System.currentTimeMillis();
        List<String> seqResults = processor.processTreeSequential(root);
        System.out.println("Sequential tree results: " + seqResults);
        System.out.println("Sequential tree processing time: " + (System.currentTimeMillis() - start) + "ms");

        start = System.currentTimeMillis();
        List<String> parResults = processor.processTreeParallel(root);
        System.out.println("Parallel tree results: " + parResults);
        System.out.println("Parallel tree processing time: " + (System.currentTimeMillis() - start) + "ms");

        processor.shutdown();
    }
}

